45	/** Cookie the register page sets when a visitor arrives via a referral link. */
46	const REF_COOKIE = "nxeon_ref";
47	/** Cookie the billing CouponField sets when a promo code is applied. */
48	const COUPON_COOKIE = "nxeon_coupon";
49	
50	/** Allocate a referral code that is unique in the DB (retry on the rare clash). */
51	async function uniqueReferralCode(): Promise<string> {
52	  for (let i = 0; i < 6; i++) {
53	    const code = generateReferralCode();
54	    const clash = await db.user.findUnique({ where: { referralCode: code } });
55	    if (!clash) return code;
56	  }
57	  // Extremely unlikely; fall back to a longer code.
58	  return generateReferralCode(12);
59	}
60	
61	async function audit(userId: string | null, action: string, detail?: string) {
62	  // Attribute to the real admin when an admin is impersonating, so customer-scoped
63	  // actions taken during impersonation aren't logged as if the customer did them.
64	  const imp = await impersonating();
65	  const actor = imp ? `actingAdmin=${imp.admin.id}` : "";
66	  const fullDetail = detail && actor ? `${detail} ${actor}` : detail || actor || undefined;
67	  await db.auditLog.create({ data: { userId, action, detail: fullDetail } });
68	}
69	
70	/** Local sentinel: renewNow's compare-and-swap lost the race (already renewed). */
71	class AlreadyRenewedError extends Error {
72	  constructor() {
73	    super("ALREADY_RENEWED");
74	    this.name = "AlreadyRenewedError";
75	  }
76	}
