78	// ---------- Auth ----------
79	
80	const credsSchema = z.object({
81	  email: z.string().max(200).email("Enter a valid email address"),
82	  password: z.string().min(8).max(200),
83	});
84	
85	export async function register(prev: any, formData: FormData): Promise<{ error?: string }> {
86	  const parsed = credsSchema
87	    .extend({
88	      name: z.string().min(1, "Enter your name").max(100, "Name is too long"),
89	      password: z
90	        .string()
91	        .min(8, "Password must be at least 8 characters")
92	        .max(200, "Password is too long")
93	        .regex(/[a-zA-Z]/, "Password must include a letter")
94	        .regex(/[0-9]/, "Password must include a number"),
95	    })
96	    .safeParse({
97	    // Canonicalise BEFORE validating, so `  Alice@Example.com ` is stored in the
98	    // one form every lookup will use. See lib/email-normalize.ts.
99	    email: normalizeEmail(formData.get("email")),
100	    password: formData.get("password"),
101	    name: formData.get("name"),
102	  });
103	  // Say what is actually wrong. This used to collapse four precise, already
104	  // written messages into "Enter a valid email, name, and password (min 8
105	  // chars)." — so a customer whose only problem was a missing digit was told
106	  // about a length rule their 8-character password already satisfied, and had
107	  // no way to work out what the form wanted. `orderServer` below has surfaced
108	  // the real issue since it was written; this is the same one line.
109	  if (!parsed.success) return { error: parsed.error.issues[0]?.message ?? "Check the form and try again." };
110	  const { email, password, name } = parsed.data;
111	
112	  // Throttle signups per email+IP (reuses the login rate-limit helper) to curb
113	  // automated account creation and welcome-credit farming.
114	  const regHdrs = await headers();
115	  const regIp = (regHdrs.get("x-forwarded-for") ?? "").split(",")[0]?.trim() || "unknown";
116	  const regRl = checkRateLimit(`register:${email}:${regIp}`, { max: 5, windowMs: 15 * 60 * 1000 });
117	  if (!regRl.ok) return { error: `Too many attempts. Try again in ${regRl.retryAfterSec}s.` };
118	
119	  const existing = await db.user.findUnique({ where: { email } });
120	  if (existing) return { error: "An account with that email already exists." };
121	
122	  // Capture a referral from the `ref` cookie (set by the register page) if the
123	  // code maps to a real user. Self-referral is impossible here (new account).
124	  const jar = await cookies();
125	  const refCode = jar.get(REF_COOKIE)?.value?.trim().toUpperCase();
126	  let referredById: string | null = null;
127	  if (refCode) {
128	    const referrer = await db.user.findUnique({ where: { referralCode: refCode } });
129	    if (referrer) referredById = referrer.id;
130	  }
131	
132	  const referralCode = await uniqueReferralCode();
133	  const user = await db.user.create({
134	    data: {
135	      email,
136	      name,
137	      passwordHash: await bcrypt.hash(password, 12),
138	      referralCode,
139	      referredById,
140	    },
141	  });
142	  await audit(user.id, "user.register", referredById ? `ref=${refCode}` : undefined);
143	  // Establish the session first so the freshly-created account is the acting user
144	  // when grantSignupCredit runs (its internal guard requires self-attribution).
145	  await createSession(user.id);
146	  // Grant signup free credit (no-op unless SIGNUP_FREE_CREDIT_CENTS > 0).
147	  try {
148	    await grantSignupCredit(user.id);
149	  } catch { /* non-fatal */ }
150	  jar.delete(REF_COOKIE);
151	  try {
152	    const { sendMail, emails } = await import("./mailer");
153	    const tpl = emails.welcome(name);
154	    await sendMail({ to: email, subject: tpl.subject, html: tpl.html, userId: user.id, kind: "welcome" });
155	  } catch { /* email is best-effort */ }
156	  // Send the verification link. Best-effort like the welcome mail and it does
157	  // NOT block the redirect: signing up and looking around stay open, only
158	  // buying and provisioning wait on the click (lib/email-verification.ts). If
159	  // this send fails the account is still usable and still resendable from the
160	  // portal banner — the customer is never stranded on a screen we control.
161	  try {
162	    const { sendVerificationEmail } = await import("./email-verification");
163	    await sendVerificationEmail(user);
164	  } catch (e) {
165	    console.error("[register] verification email failed:", e);
166	  }
167	  redirect("/dashboard");
168	}
