170	export async function login(
171	  prev: any,
172	  formData: FormData,
173	): Promise<{ error?: string; needs2fa?: boolean }> {
174	  const parsed = credsSchema.safeParse({
175	    // Same canonical form the account was stored under (lib/email-normalize.ts).
176	    // Without this, signing in as `Alice@Example.com` missed a row stored as
177	    // `alice@example.com` and reported bad credentials for a correct password.
178	    email: normalizeEmail(formData.get("email")),
179	    password: formData.get("password"),
180	  });
181	  if (!parsed.success) return { error: "Invalid email or password." };
182	
183	  // App-level throttle per email+IP over a 15 min window. The max-attempts cap is
184	  // admin-configurable (`login_ratelimit_max`, default 10) rather than hardcoded.
185	  const hdrs = await headers();
186	  const ip = (hdrs.get("x-forwarded-for") ?? "").split(",")[0]?.trim() || "unknown";
187	  const rlId = `${parsed.data.email}:${ip}`;
188	  const maxAttempts = Math.max(1, await getSettingInt("login_ratelimit_max", 10));
189	  const rl = checkRateLimit(`login:${rlId}`, { max: maxAttempts, windowMs: 15 * 60 * 1000 });
190	  if (!rl.ok) return { error: `Too many attempts. Try again in ${rl.retryAfterSec}s.` };
191	
192	  const user = await db.user.findUnique({ where: { email: parsed.data.email } });
193	  if (!user || !(await bcrypt.compare(parsed.data.password, user.passwordHash))) {
194	    return { error: "Invalid email or password." };
195	  }
196	  if (user.suspended) return { error: "This account is suspended." };
197	
198	  // Two-factor challenge, if enabled on the account.
199	  if (user.totpEnabled) {
200	    const code = String(formData.get("code") ?? "").trim();
201	    if (!code) return { error: "Enter your 2FA code to continue.", needs2fa: true };
202	    if (!(await verifyTotpForUser(user.id, code))) {
203	      return { error: "Invalid 2FA code.", needs2fa: true };
204	    }
205	  }
206	
207	  resetRateLimit(`login:${rlId}`);
208	  await audit(user.id, "user.login");
209	  await createSession(user.id);
210	  // Land where they were HEADING, not on a generic dashboard.
211	  //
212	  // Public CTAs like "Migrate free →" send a logged-out visitor into
213	  // /dashboard/..., which bounces to /login and — until now — discarded what they
214	  // clicked. They signed in and arrived somewhere unrelated, with no route back to
215	  // the thing they wanted. Seven CTAs did this, the worst being "Contact support"
216	  // on the PUBLIC help page, where a prospect met a login wall instead of /contact.
217	  //
218	  // `safeNext` only ever returns a path on THIS site (see its definition): an
219	  // open redirect on a login form is a phishing primitive, so an absolute URL, a
220	  // protocol-relative `//evil.test` or anything that is not a single-slash path is
221	  // discarded rather than sanitised.
222	  const next = safeNext(formData.get("next"));
223	  redirect(next ?? (user.role === "ADMIN" ? "/admin" : "/dashboard"));
224	}
225	
226	export async function logout() {
227	  await destroySession();
228	  redirect("/login");
229	}
