233	const orderSchema = z.object({
234	  planId: z.string().min(1),
235	  osTemplateId: z.string().min(1),
236	  hostname: z
237	    .string()
238	    .min(3)
239	    .max(40)
240	    .regex(/^[a-z0-9]([a-z0-9-]*[a-z0-9])?$/i, "Hostname: letters, digits, hyphens"),
241	});
