243	/** Pick the least-committed enabled node (RAM headroom). Falls back to primary. */
244	async function scheduleNode(planRamMB: number) {
245	  const nodes = await db.node.findMany({ where: { enabled: true, status: "ONLINE" } });
246	  if (nodes.length === 0) return null;
247	  const loads = await Promise.all(
248	    nodes.map(async (n) => {
249	      const agg = await db.server.findMany({
250	        where: { nodeId: n.id, status: { notIn: ["DELETING"] } },
251	        select: { plan: { select: { ramMB: true } } },
252	      });
253	      const used = agg.reduce((s, r) => s + r.plan.ramMB, 0);
254	      return { node: n, free: n.capacityRamMB - used };
255	    })
256	  );
257	  loads.sort((a, b) => b.free - a.free);
258	  const best = loads[0];
259	  if (best.free < planRamMB) return best.node; // oversell guard handled by capacityCheck; still return best
260	  return best.node;
261	}
262	
263	/**
264	 * Enforce the admin-configured per-user server cap (`max_servers_per_user`,
265	 * default 10; 0 = unlimited). Counts every server the user owns that isn't being
266	 * torn down (DELETING). Returns an error message when the cap is reached, else null.
267	 */
268	async function serverLimitError(userId: string): Promise<string | null> {
269	  const cap = await getSettingInt("max_servers_per_user", 10);
270	  if (cap <= 0) return null; // 0 (or negative) = unlimited
271	  const owned = await db.server.count({ where: { userId, status: { notIn: ["DELETING"] } } });
272	  if (owned >= cap) {
273	    return `You've reached your limit of ${cap} server${cap === 1 ? "" : "s"}. Delete one or contact support to raise the cap.`;
274	  }
275	  return null;
276	}
277	
278	export async function orderServer(prev: any, formData: FormData): Promise<{ error?: string }> {
279	  const user = await requireUser();
280	  // Spend path: never move a customer's money while an admin is impersonating them.
281	  await assertNotImpersonating();
282	  // …and never build a server for an address we have never reached. The root
283	  // password, the expiry warning and the dunning sequence all go there.
284	  const unverified = await emailVerificationError(user);
285	  if (unverified) return { error: unverified };
286	  // Refuse new orders once the user is at their server cap.
287	  const limitErr = await serverLimitError(user.id);
288	  if (limitErr) return { error: limitErr };
289	  const parsed = orderSchema.safeParse({
290	    planId: formData.get("planId"),
291	    osTemplateId: formData.get("osTemplateId"),
292	    hostname: formData.get("hostname"),
293	  });
294	  if (!parsed.success) return { error: parsed.error.issues[0]?.message ?? "Invalid input." };
295	
296	  const plan = await db.plan.findUnique({ where: { id: parsed.data.planId } });
297	  const os = await db.osTemplate.findUnique({ where: { id: parsed.data.osTemplateId } });
298	  if (!plan?.active || !os?.active) return { error: "Plan or OS not available." };
299	
300	  // Image requirements (control panels/apps need more resources)
301	  if (plan.ramMB < os.minRamMB || plan.diskGB < os.minDiskGB) {
302	    return {
303	      error: `${os.name} needs at least ${os.minRamMB / 1024} GB RAM and ${os.minDiskGB} GB disk — choose a larger plan.`,
304	    };
305	  }
306	
307	  const cap = await capacityCheck(plan.id);
308	  if (!cap.ok) return { error: cap.reason };
309	
310	  // Optional: node (location) selection, else auto-schedule
311	  const requestedNodeId = String(formData.get("nodeId") ?? "");
312	  let nodeId: string | null = null;
313	  if (requestedNodeId) {
314	    const n = await db.node.findFirst({ where: { id: requestedNodeId, enabled: true } });
315	    if (!n) return { error: "Selected location is not available." };
316	    nodeId = n.id;
317	  } else {
318	    const n = await scheduleNode(plan.ramMB);
319	    nodeId = n?.id ?? null;
320	  }
321	
322	  // Add-ons (booleans)
323	  const addons = {
324	    malwareScanner: formData.get("addon_malware") === "1",
325	    dailyBackup: formData.get("addon_backup") === "1",
326	    docker: formData.get("addon_docker") === "1",
327	  };
328	
329	  // Optional SSH key added at deploy time
330	  const newKey = String(formData.get("sshPublicKey") ?? "").trim();
331	  const keyName = String(formData.get("sshKeyName") ?? "deploy-key").slice(0, 60);
332	
333	  // Billing term (monthly / annual / 2yr / 3yr) with commitment discount
334	  const term = vpsTerm(Number(formData.get("termMonths") ?? 1));
335	  const wantsDedicatedIp = formData.get("dedicatedIp") === "1";
336	  const ipCents = wantsDedicatedIp ? (await dedicatedIpMonthlyCents()) * term.months : 0;
337	  // Seasonal promo = HONEST intro discount on the plan's FIRST-term charge only.
338	  // Mirrors lib/order.ts orderQuote so every VPS charge path agrees. Renewals in
339	  // worker/billing.ts bill the regular vpsTermPriceCents (untouched), so the
340	  // strikethrough shown on marketing pages is the real renewal price and this
341	  // discounted value is the real first-term price — displayed === charged.
342	  // (Dedicated IP is billed at full price; the promo only touches the plan.)
343	  const regularPlanCents = vpsTermPriceCents(plan.priceCents, term.months);
344	  const promo = currentPromo(new Date());
345	  const chargeCents = promoPriceCents(regularPlanCents, promo) + ipCents;
346	  const promoNote = promo.discountPercent > 0 ? ` · ${promo.name} ${promo.discountPercent}% off first term` : "";
347	
348	  const isAdmin = user.role === "ADMIN";
349	  const freeRequested = formData.get("free") === "1" && isAdmin;
350	
351	  if (!freeRequested && user.balanceCents < chargeCents) {
352	    return { error: "Insufficient balance. Top up your wallet first." };
353	  }
354	
355	  let server;
356	  try {
357	    server = await db.$transaction(async (tx) => {
358	    if (!freeRequested) {
359	      await debitWallet(tx, user.id, chargeCents);
360	      await tx.walletTransaction.create({
361	        data: {
362	          userId: user.id,
363	          amountCents: -chargeCents,
364	          description: `Order: ${plan.name} VPS (${parsed.data.hostname}) — ${term.label}${promoNote}`,
365	        },
366	      });
367	      // PAID invoice for the initial order (one distinct charge per order — the
368	      // new server row is created below, so there is no replay to dedupe).
369	      await tx.invoice.create({
370	        data: invoiceCreateData({
371	          userId: user.id,
372	          description: `Order: ${plan.name} VPS (${parsed.data.hostname}) — ${term.label}${promoNote}`,
373	          status: "PAID",
374	          period: { start: new Date(), end: addMonths(new Date(), term.months) },
375	          lineItems: [
376	            { description: `${plan.name} VPS (${parsed.data.hostname}) — ${term.label}${promoNote}`, qty: 1, unitCents: chargeCents, amountCents: chargeCents },
377	          ],
378	        }),
379	      });
380	    }
381	    if (newKey && /^(ssh-(rsa|ed25519)|ecdsa-sha2-\S+)\s+\S+/.test(newKey)) {
382	      const exists = await tx.sshKey.findFirst({ where: { userId: user.id, publicKey: newKey } });
383	      if (!exists) await tx.sshKey.create({ data: { userId: user.id, name: keyName, publicKey: newKey } });
384	    }
385	    const s = await tx.server.create({
386	      data: {
387	        name: parsed.data.hostname,
388	        hostname: parsed.data.hostname,
389	        userId: user.id,
390	        planId: plan.id,
391	        osTemplateId: os.id,
392	        nodeId,
393	        addons,
394	        termMonths: term.months,
395	        // The rate this term was sold at — mirrors lib/order.ts placeOrder, since
396	        // `chargeCents` above is promoPriceCents(regularPlanCents, promo). Every
397	        // later proration prices against this, never against the promo running at
398	        // resize time. 100 on a free grant: nothing paid, nothing to prorate out.
399	        termPromoPercent: freeRequested ? 100 : promo.discountPercent,
400	        wantsDedicatedIp,
401	        isFree: freeRequested,
402	        expiresAt: freeRequested ? null : addMonths(new Date(), term.months),
403	      },
404	    });
405	    await tx.job.create({ data: { type: "PROVISION", serverId: s.id } });
406	    return s;
407	    });
408	  } catch (e) {
409	    if (e instanceof InsufficientBalanceError) {
410	      return { error: "Insufficient balance. Top up your wallet first." };
411	    }
412	    throw e;
413	  }
414	
415	  await audit(user.id, "server.order", `${server.id} image=${os.slug} plan=${plan.slug} term=${term.months}mo free=${freeRequested}`);
416	  // A first paid order can unlock a referral reward (free admin grants don't count).
417	  if (!freeRequested) {
418	    try {
419	      await maybeRewardReferral(user.id);
420	    } catch { /* non-fatal */ }
421	  }
422	  redirect(`/dashboard/servers/${server.id}`);
423	}
