425	/**
426	 * Deploy flow that does NOT require pre-funding the wallet. If the wallet covers
427	 * the order (or it's a free admin grant) it provisions immediately; otherwise it
428	 * returns a Stripe Checkout URL for the order total, and the Stripe confirm route
429	 * provisions the server on successful payment.
430	 */
431	export async function payAndDeploy(
432	  prev: any,
433	  formData: FormData,
434	): Promise<{ error?: string; checkoutUrl?: string }> {
435	  const user = await requireUser();
436	  // Spend path: same impersonation guard as orderServer.
437	  await assertNotImpersonating();
438	  // Same verification gate as orderServer. This is the CARD path, so it is the
439	  // one where an unreachable address is most expensive: without it we would take
440	  // a real payment for a machine whose credentials have nowhere to go.
441	  const unverified = await emailVerificationError(user);
442	  if (unverified) return { error: unverified };
443	  // Same per-user server cap as orderServer (this is the card-pay deploy path).
444	  const limitErr = await serverLimitError(user.id);
445	  if (limitErr) return { error: limitErr };
446	  const intent = intentFromFormData(formData);
447	
448	  let quote;
449	  try {
450	    quote = await orderQuote(intent);
451	  } catch (e) {
452	    if (e instanceof OrderError) return { error: e.message };
453	    throw e;
454	  }
455	
456	  const isAdmin = user.role === "ADMIN";
457	  const freePath = !!intent.free && isAdmin;
458	
459	  // Wallet-aware split. The customer's Review screen computes the exact same split
460	  // (lib/wallet-split.ts) from the same inputs, so what they see === what we charge.
461	  // `useWallet` defaults ON (only "0" turns it off) so existing forms keep applying
462	  // the balance. Free admin grants skip the split entirely (no money moves).
463	  const useWallet = formData.get("useWallet") !== "0";
464	  const { walletApplied, cardCents } = freePath
465	    ? { walletApplied: 0, cardCents: 0 }
466	    : walletSplit({ dueCents: quote.chargeCents, balanceCents: user.balanceCents, useWallet });
467	
468	  // Card portion is $0 (free admin grant, or the wallet fully covers the charge) →
469	  // provision straight away. placeOrder debits the FULL chargeCents from the wallet
470	  // (or nothing, for a free grant); the balance check inside it holds because a
471	  // $0 card portion means balance >= chargeCents.
472	  if (freePath || cardCents <= 0) {
473	    let serverId: string;
474	    try {
475	      serverId = await placeOrder(user, intent);
476	    } catch (e) {
477	      if (e instanceof OrderError) return { error: e.message };
478	      throw e;
479	    }
480	    redirect(`/dashboard/servers/${serverId}`);
481	  }
482	
483	  // Card portion > 0 → charge ONLY the remainder on the card (not the full total).
484	  // On payment success the confirm route credits this card amount to the wallet and
485	  // then placeOrder debits the full chargeCents, so the wallet naturally absorbs
486	  // `walletApplied` and the card the rest — the wallet is never touched before the
487	  // card clears. (walletApplied is implied by cardCents vs. the recomputed charge,
488	  // so it needs no separate metadata field.)
489	  // The price is handed over EXPLICITLY, from the very quote the wallet split above
490	  // was computed from. Without this argument `createOrderCheckout` re-quotes
491	  // internally, microseconds later, from its own `new Date()` — the same function,
492	  // so no formula can drift, but two different instants. A promo boundary (or an
493	  // operator changing a plan price) falling between them would mean the card leg
494	  // and the stamped total were priced against two different worlds, and the wallet
495	  // would silently absorb the difference. One quote, one price, one charge.
496	  const url = await createOrderCheckout(user, cardCents, intent, orderPriceOf(quote));
497	  if (!url) return { error: "Card payments aren't set up yet — top up your wallet to deploy." };
498	  return { checkoutUrl: url };
499	}
