503	async function ownedServer(serverId: string) {
504	  const user = await requireUser();
505	  const server = await db.server.findUnique({ where: { id: serverId } });
506	  if (!server) throw new Error("Not found");
507	  if (server.userId !== user.id && user.role !== "ADMIN") throw new Error("Forbidden");
508	  return { user, server };
509	}
510	
511	export async function serverAction(serverId: string, action: string) {
512	  const { user, server } = await ownedServer(serverId);
513	  const allowed: Record<string, "START" | "STOP" | "REBOOT" | "REINSTALL" | "DELETE"> = {
514	    start: "START",
515	    stop: "STOP",
516	    reboot: "REBOOT",
517	    reinstall: "REINSTALL",
518	    delete: "DELETE",
519	  };
520	  const type = allowed[action];
521	  if (!type) throw new Error("Invalid action");
522	  if (server.status === "SUSPENDED" && user.role !== "ADMIN") {
523	    throw new Error("Server is suspended");
524	  }
525	
526	  // A reinstall wipes the whole VM, including any block-storage volume the VM
527	  // owns (Proxmox `qm destroy --purge` frees every disk for that vmid).
528	  //
529	  // Count volumes by `serverId` ALONE, never by `status: "ATTACHED"`. Detaching
530	  // deliberately keeps `serverId` set so the volume can be re-attached
531	  // (worker/volumes.ts) — the disk stays owned by this vmid as an `unusedN`
532	  // entry, and PVE's destroy_vm frees unused disks too (include_unused => 1).
533	  // Filtering on ATTACHED therefore missed the worst case: customer fills a
534	  // volume, clicks Detach (the UI promises "Data is preserved."), clicks
535	  // Reinstall — both guards see zero attached volumes, and the purge takes the
536	  // data with it. `reinstallToOs` in actions-server-lifecycle.ts always counted
537	  // by serverId; this path did not. That asymmetry was the bug.
538	  if (type === "REINSTALL") {
539	    const pinnedVolumes = await db.volume.count({ where: { serverId } });
540	    if (pinnedVolumes > 0) {
541	      throw new Error(
542	        "Delete your data volume(s) before reinstalling — a reinstall wipes the whole server, and that includes detached volumes still assigned to it. Open Volumes first.",
543	      );
544	    }
545	  }
546	
547	  const pending = await db.job.count({
548	    where: { serverId, status: { in: ["QUEUED", "RUNNING"] } },
549	  });
550	  if (pending > 0) return; // debounce: one job at a time per server
551	
552	  if (type === "DELETE") {
553	    await db.server.update({ where: { id: serverId }, data: { status: "DELETING" } });
554	  }
555	  await db.job.create({ data: { type, serverId } });
556	  await audit(user.id, `server.${action}`, serverId);
557	  if (type === "DELETE") redirect(user.role === "ADMIN" ? "/admin/servers" : "/dashboard");
558	  revalidatePath(`/dashboard/servers/${serverId}`);
559	}
