562	
563	export async function topUp(prev: any, formData: FormData): Promise<{ error?: string }> {
564	  const user = await requireUser();
565	  // Spend/credit path: block while impersonating so an admin can't mint or move
566	  // a customer's balance on their behalf.
567	  await assertNotImpersonating();
568	  // Security: never mint free wallet balance in production. The demo gateway that
569	  // credits without a real payment is only ever acceptable in non-production, and
570	  // is refused outright when NODE_ENV === "production" regardless of Stripe.
571	  if (process.env.NODE_ENV === "production") {
572	    return { error: "Please add funds with a card via the secure checkout." };
573	  }
574	  // Once Stripe is configured, the demo gateway is hard-disabled — top-ups must
575	  // go through Checkout.
576	  const { stripeConfigured } = await import("./stripe");
577	  if (stripeConfigured()) {
578	    return { error: "Please add funds with a card via the secure checkout." };
579	  }
580	  // Throttle demo top-ups per user+IP to prevent rapid free-credit minting.
581	  const topupHdrs = await headers();
582	  const topupIp = (topupHdrs.get("x-forwarded-for") ?? "").split(",")[0]?.trim() || "unknown";
583	  const topupRl = checkRateLimit(`topup:${user.id}:${topupIp}`, { max: 10, windowMs: 60 * 60 * 1000 });
584	  if (!topupRl.ok) {
585	    return { error: `Too many top-up attempts. Try again in ${topupRl.retryAfterSec}s.` };
586	  }
587	  const amount = Number(formData.get("amount"));
588	  if (!Number.isFinite(amount) || amount < 1 || amount > 1000) {
589	    return { error: "Amount must be between $1 and $1000." };
590	  }
591	  const cents = Math.round(amount * 100);
592	  // Enforce the admin-configured minimum top-up (`min_topup_cents`, default 500).
593	  const minTopup = await getSettingInt("min_topup_cents", 500);
594	  if (cents < minTopup) {
595	    return { error: `Minimum top-up is $${(minTopup / 100).toFixed(2)}.` };
596	  }
597	
598	  // Optional promo code: applied via the COUPON_COOKIE the billing CouponField
599	  // sets. applyCouponToTopup re-validates for this user against the real amount.
600	  const jar = await cookies();
601	  const couponCode = jar.get(COUPON_COOKIE)?.value?.trim();
602	  let bonusCents = 0;
603	  let couponId: string | null = null;
604	  let couponLabel = "";
605	  if (couponCode) {
606	    const result = await applyCouponToTopup(couponCode, cents);
607	    if (result.ok) {
608	      bonusCents = result.bonusCents;
609	      couponId = result.couponId;
610	      couponLabel = result.label;
611	    } else {
612	      // REFUSE, don't silently drop. The old code fell through and completed the
613	      // top-up with no bonus and no message, so a code that passed validation at
614	      // the preview amount but fails against the real one (a `minAmountCents`
615	      // floor, an exhausted limit, an expiry) simply vanished — the customer paid
616	      // expecting a bonus and got nothing, with nowhere to look. Nothing has been
617	      // charged at this point, so stopping is free and the customer can retry
618	      // without the code or with a larger amount.
619	      return {
620	        error:
621	          `${result.error ?? "That promo code can't be applied to this amount."} ` +
622	          `Nothing has been charged — adjust the amount or remove the code and try again.`,
623	      };
624	    }
625	  }
626	
627	  await db.$transaction([
628	    db.user.update({
629	      where: { id: user.id },
630	      data: { balanceCents: { increment: cents + bonusCents } },
631	    }),
632	    db.walletTransaction.create({
633	      data: { userId: user.id, amountCents: cents, description: "Wallet top-up (demo gateway)" },
634	    }),
635	    ...(bonusCents > 0 && couponId
636	      ? [
637	          db.walletTransaction.create({
638	            data: {
639	              userId: user.id,
640	              amountCents: bonusCents,
641	              description: `Promo ${couponCode!.toUpperCase()} — ${couponLabel}`,
642	            },
643	          }),
644	          db.couponRedemption.create({
645	            data: { couponId, userId: user.id, amountCents: bonusCents, context: "topup" },
646	          }),
647	          db.coupon.update({
648	            where: { id: couponId },
649	            data: { timesRedeemed: { increment: 1 } },
650	          }),
651	        ]
652	      : []),
653	  ]);
654	  jar.delete(COUPON_COOKIE);
655	  await audit(user.id, "wallet.topup", `$${amount}${bonusCents > 0 ? ` +bonus $${(bonusCents / 100).toFixed(2)}` : ""}`);
656	  // First successful paid action may unlock a referral reward for both parties.
657	  try {
658	    await maybeRewardReferral(user.id);
659	  } catch { /* non-fatal */ }
660	  revalidatePath("/dashboard/billing");
661	  return {};
662	}
