677	export async function renewNow(serverId: string): Promise<{ error?: string } | void> {
678	  // Spend path: block wallet debits while an admin is impersonating.
679	  await assertNotImpersonating();
680	  const { user, server } = await ownedServer(serverId);
681	  if (server.isFree || !server.expiresAt) return;
682	  // A MANUAL renewal is a fresh purchase decision, so it is gated. Note this
683	  // cannot strand an existing customer: every account that owns a server today
684	  // predates verification and is grandfathered, and the automatic renewal in
685	  // worker/billing.ts does not pass through here at all — nobody's server lapses
686	  // because of this check.
687	  const unverified = await emailVerificationError(user);
688	  if (unverified) return { error: unverified };
689	  const plan = await db.plan.findUnique({ where: { id: server.planId } });
690	  if (!plan) return;
691	  // A game server carries BOTH a base `planId` and a `gamePlanId`, and it is sold
692	  // at the game plan's FLAT price. Reading only `plan.priceCents` here charged a
693	  // game-server owner the base VPS term price instead — `minecraft-mm8w85` sold at
694	  // $4.99 on a Starter base plan would have been billed $8.99, an 80% overcharge.
695	  const gamePlan = server.gamePlanId
696	    ? await db.gamePlan.findUnique({
697	        where: { id: server.gamePlanId },
698	        select: { name: true, priceCents: true, termMonths: true },
699	      })
700	    : null;
701	  // Charge the IP surcharge based on the ACTUAL allocated IP (matching worker/
702	  // billing.ts), not the intent flag — a NAT-fallback server never gets billed.
703	  const hasDedicatedIp = !!(await db.dedicatedIp.findFirst({
704	    where: { serverId }, select: { id: true },
705	  }));
706	  // Priced through `renewalCharge` — the SAME function the automatic renewal sweep
707	  // in worker/billing.ts and the saved-card path use. Not a second copy of the
708	  // arithmetic: see lib/renewal-quote.ts for both incidents that produced this
709	  // rule, the second of which was a fresh duplicate written hours after the first.
710	  const quote = renewalQuote(
711	    {
712	      termMonths: server.termMonths,
713	      extraDiskGB: server.extraDiskGB,
714	      plan: { name: plan.name, priceCents: plan.priceCents },
715	      gamePlan,
716	      dedicatedIp: hasDedicatedIp ? {} : null,
717	    },
718	    {
719	      ipMonthlyCents: hasDedicatedIp ? await dedicatedIpMonthlyCents() : 0,
720	      extraDiskPerGbCents: await extraDiskPerGbCents(),
721	    },
722	  );
723	  const renewCents = quote.totalCents;
724	  const term = { months: quote.months };
725	  const extraDiskMonthly = await extraDiskMonthlyCents(server.extraDiskGB);
726	  const extraDiskCents = gamePlan ? 0 : extraDiskMonthly * quote.months;
727	  const owner = await db.user.findUnique({ where: { id: server.userId } });
728	  if (!owner || owner.balanceCents < renewCents) {
729	    return { error: "Insufficient balance — top up your wallet first." };
730	  }
731	
732	  // `E` is the expiry we read OUTSIDE the transaction. We advance it with a
733	  // compare-and-swap on that exact value so two concurrent "Renew now" clicks
734	  // can't both read E, both debit, and both write E+term (double-charge, one
735	  // term granted). Only the CAS that matches E wins; the loser is a no-op.
736	  const E = server.expiresAt;
737	  const base = new Date(Math.max(E.getTime(), Date.now()));
738	  const newExpiry = addMonths(base, term.months);
739	
740	  // `renewCents` above is `vpsTermPriceCents(...)` — the REGULAR price, with no
741	  // seasonal promo applied. That is exactly what lib/promotions.ts promises: the
742	  // strikethrough on the marketing page is the real renewal price. So the months
743	  // being added here are sold at 0% off, and the term's stored rate has to say so.
744	  //
745	  // BLENDED, not overwritten. A customer can renew early, stacking a full-price
746	  // term on top of months still running at an intro discount. Overwriting would
747	  // silently reprice those earlier months to full list — and that is the profitable
748	  // direction: buy 36 months at 45% off, renew once at full price, and every one of
749	  // the original discounted months would suddenly credit at the full rate on a
750	  // downgrade. Blending keeps the cash value of the window invariant.
751	  const renewedPercent = prorateBlendPercent({
752	    currentPercent: resolveTermPromoPercent(server.termPromoPercent),
753	    currentMonths: remainingMonths(E, Date.now()),
754	    addedPercent: 0,
755	    addedMonths: term.months,
756	  });
757	  try {
758	    await db.$transaction(async (tx) => {
759	      // Compare-and-swap the expiry first; if it no longer equals E another
760	      // renewal already advanced it — bail without charging (tx rolls back).
761	      const adv = await tx.server.updateMany({
762	        where: { id: serverId, expiresAt: E },
763	        data: {
764	          expiresAt: newExpiry,
765	          termPromoPercent: renewedPercent,
766	          suspendedNote: null,
767	          suspendReason: null,
768	        },
769	      });
770	      if (adv.count === 0) throw new AlreadyRenewedError();
771	      // Atomic guarded debit: a concurrent spend can't drive the wallet negative.
772	      await debitWallet(tx, server.userId, renewCents);
773	      await tx.walletTransaction.create({
774	        data: {
775	          userId: server.userId,
776	          amountCents: -renewCents,
777	          description: `Renewal: ${quote.label} (${server.hostname}) — ${quote.durationLabel}`,
778	        },
779	      });
780	      // PAID invoice inside the same CAS-guarded tx: a losing concurrent "Renew
781	      // now" throws AlreadyRenewedError and rolls back, so no duplicate invoice.
782	      await tx.invoice.create({
783	        data: invoiceCreateData({
784	          userId: server.userId,
785	          description: `Renewal: ${quote.label} (${server.hostname}) — ${quote.durationLabel}`,
786	          status: "PAID",
787	          period: { start: E, end: newExpiry },
788	          lineItems: [
789	            {
790	              description: `${quote.label} (${server.hostname}) — ${quote.durationLabel}`,
791	              qty: 1,
792	              unitCents: renewCents - extraDiskCents,
793	              amountCents: renewCents - extraDiskCents,
794	            },
795	            ...(extraDiskCents > 0
796	              ? [
797	                  {
798	                    description: `${extraDiskLabel(server.extraDiskGB)} — ${server.hostname} (permanent, $${(extraDiskMonthly / 100).toFixed(2)}/mo)`,
799	                    qty: 1,
800	                    unitCents: extraDiskCents,
801	                    amountCents: extraDiskCents,
802	                  },
803	                ]
804	              : []),
805	          ],
806	        }),
807	      });
808	    });
809	  } catch (e) {
810	    if (e instanceof InsufficientBalanceError) return { error: "Insufficient balance — top up your wallet first." };
811	    if (e instanceof AlreadyRenewedError) return { error: "This server was just renewed — refresh to see the new expiry." };
812	    throw e;
813	  }
814	  await audit(user.id, "server.renew_now", serverId);
815	
816	  // An UNPAID-suspended server springs back to life once paid — but only that
817	  // kind. This used to fire for ANY suspended server, so a customer suspended for
818	  // outbound abuse could click "Renew now", pay, and put themselves straight back
819	  // on the network, undoing an abuse or admin action with a card. Legacy rows with
820	  // a null `suspendReason` are not auto-lifted; an admin can clear those by hand.
821	  if (server.status === "SUSPENDED" && server.suspendReason === "UNPAID") {
822	    const pending = await db.job.count({
823	      where: { serverId, status: { in: ["QUEUED", "RUNNING"] } },
824	    });
825	    if (pending === 0) await db.job.create({ data: { type: "UNSUSPEND", serverId } });
826	  }
827	  revalidatePath(`/dashboard/servers/${serverId}`);
828	}
