129	export async function resizeServer(
130	  serverId: string,
131	  planId: string,
132	  useWallet: boolean = true,
133	): Promise<{ error?: string; checkoutUrl?: string }> {
134	  const { user, server } = await ownedServer(serverId);
135	  // Purchase gate: an upgrade is a charge (wallet or card). Downgrades live in
136	  // resizeServerDown and are deliberately NOT gated — that path REFUNDS, and
137	  // stopping a customer from spending LESS would be a gate with no one to
138	  // protect. See lib/email-verification.ts.
139	  const unverified = await emailVerificationError(user);
140	  if (unverified) return { error: unverified };
141	
142	  // Validate + price the upgrade (ownership already checked above). resizeQuote
143	  // recomputes the exact prorated charge over the remaining term.
144	  let quote;
145	  try {
146	    quote = await resizeQuote(serverId, planId);
147	  } catch (e) {
148	    if (e instanceof ResizeError) return { error: e.message };
149	    throw e;
150	  }
151	  const { newPlan, prorateCents } = quote;
152	
153	  // Wallet-aware split — identical logic to the deploy flow. ResizePicker computes
154	  // the same split (lib/wallet-split.ts) so displayed === charged.
155	  const { cardCents } = walletSplit({
156	    dueCents: prorateCents,
157	    balanceCents: user.balanceCents,
158	    useWallet,
159	  });
160	
161	  // Card portion > 0 → charge ONLY the remainder on the card (not the full
162	  // proration). The confirm route credits the card amount to the wallet and then
163	  // debits the FULL proration (encoded as chargeCents), so the wallet absorbs its
164	  // share and the card the rest — wallet never touched before the card clears.
165	  if (cardCents > 0) {
166	    const url = await createResizeCheckout(user, cardCents, {
167	      serverId,
168	      planId,
169	      planName: newPlan.name,
170	      prorateCents,
171	    });
172	    if (!url) {
173	      return {
174	        error: `Upgrading costs $${(prorateCents / 100).toFixed(2)} for the rest of your term, and card payments aren't set up — top up your wallet first.`,
175	      };
176	    }
177	    return { checkoutUrl: url };
178	  }
179	
180	  // Card portion is $0 (wallet fully covers it, or the charge is $0 for free/admin
181	  // servers) → apply instantly, debiting the full proration from the wallet.
182	  try {
183	    await applyResize({ serverId, planId, actorUserId: user.id });
184	  } catch (e) {
185	    if (e instanceof ResizeError) return { error: e.message };
186	    if (e instanceof InsufficientBalanceError) return { error: "Insufficient balance — top up your wallet first." };
187	    throw e;
188	  }
189	  revalidatePath(`/dashboard/servers/${serverId}`);
190	  return {};
191	}
