213	import { SSH_PORT_START as PF_MIN, SSH_PORT_END as PF_MAX } from "./ipam";
214	const MAX_FORWARDS_PER_SERVER = 10;
215	
216	export async function addPortForward(prev: any, formData: FormData): Promise<{ error?: string }> {
217	  const serverId = String(formData.get("serverId") ?? "");
218	  const { user, server } = await ownedServer(serverId);
219	  const parsed = z
220	    .object({
221	      guestPort: z.coerce.number().int().min(1).max(65535),
222	      protocol: z.enum(["tcp", "udp"]),
223	    })
224	    .safeParse({ guestPort: formData.get("guestPort"), protocol: formData.get("protocol") ?? "tcp" });
225	  if (!parsed.success) return { error: "Invalid port." };
226	
227	  const count = await db.portForward.count({ where: { serverId } });
228	  if (count >= MAX_FORWARDS_PER_SERVER) return { error: `Limit of ${MAX_FORWARDS_PER_SERVER} forwards reached.` };
229	
230	  const used = new Set([
231	    ...(await db.portForward.findMany({ select: { publicPort: true } })).map((p) => p.publicPort),
232	    ...(await db.server.findMany({ where: { sshPort: { not: null } }, select: { sshPort: true } })).map((s) => s.sshPort!),
233	  ]);
234	  let publicPort = 0;
235	  for (let p = PF_MIN; p <= PF_MAX; p++) {
236	    if (!used.has(p)) { publicPort = p; break; }
237	  }
238	  if (!publicPort) return { error: "No public ports available." };
239	
240	  await db.portForward.create({
241	    data: { serverId, publicPort, guestPort: parsed.data.guestPort, protocol: parsed.data.protocol },
242	  });
243	  await db.job.create({ data: { type: "SYNC_FORWARDS", serverId } });
244	  await db.auditLog.create({
245	    data: { userId: user.id, action: "server.portforward_add", detail: `${serverId} :${publicPort}->${parsed.data.guestPort}/${parsed.data.protocol}` },
246	  });
247	  revalidatePath(`/dashboard/servers/${serverId}`);
248	  return {};
249	}
