11	// Block storage volumes: add-on disks a customer can order, then attach to /
12	// detach from one of their running servers. A volume is billed per GB / month.
13	// The physical Proxmox disk only exists once a volume has been attached at least
14	// once; `Volume.diskName` tracks where that disk currently lives on the VM
15	// (`scsiN` while attached, `unusedN` while detached) and `Volume.serverId` the
16	// VM that physically holds it. See worker/volumes.ts for the Proxmox side.
17	
18	const MIN_GB = 1;
19	const MAX_GB = 2000;
20	
21	/** Price (in cents) for a volume of `sizeGB`, per-GB/month from Settings. */
22	export async function volumePriceCents(sizeGB: number): Promise<number> {
23	  const perGb = await getSettingInt("volume_price_cents_per_gb", 10);
24	  return Math.max(0, Math.round(sizeGB)) * perGb;
25	}
26	
27	async function ownedVolume(volumeId: string) {
28	  const user = await requireUser();
29	  const volume = await db.volume.findUnique({ where: { id: volumeId } });
30	  if (!volume) throw new Error("Not found");
31	  if (volume.userId !== user.id && user.role !== "ADMIN") throw new Error("Forbidden");
32	  return { user, volume };
33	}
34	
35	async function ownedServer(serverId: string) {
36	  const user = await requireUser();
37	  const server = await db.server.findUnique({ where: { id: serverId } });
38	  if (!server) throw new Error("Not found");
39	  if (server.userId !== user.id && user.role !== "ADMIN") throw new Error("Forbidden");
40	  return { user, server };
41	}
42	
43	/** Reject if the server already has a job queued or running (one in-flight per server). */
44	async function serverBusy(serverId: string): Promise<boolean> {
45	  const pending = await db.job.count({
46	    where: { serverId, status: { in: ["QUEUED", "RUNNING"] } },
47	  });
48	  return pending > 0;
49	}
