51	/**
52	 * Order a new block storage volume: debit the wallet up-front (one month) and
53	 * create the Volume row PENDING plus a VOLUME_CREATE job. The job flips it to
54	 * DETACHED (available to attach). No physical disk is created until attach.
55	 */
56	export async function orderVolume(
57	  name: string,
58	  sizeGB: number
59	): Promise<{ error?: string; id?: string }> {
60	  const user = await requireUser();
61	  // Purchase gate: an unverified address means we cannot reach the person we
62	  // are about to charge. See lib/email-verification.ts.
63	  const unverified = await emailVerificationError(user);
64	  if (unverified) return { error: unverified };
65	
66	  const clean = (name ?? "")
67	    .replace(/[\x00-\x1f\x7f]/g, "")
68	    .replace(/\s+/g, " ")
69	    .trim();
70	  if (clean.length < 2 || clean.length > 40) {
71	    return { error: "Name must be 2–40 characters." };
72	  }
73	  const size = Math.round(Number(sizeGB));
74	  if (!Number.isFinite(size) || size < MIN_GB || size > MAX_GB) {
75	    return { error: `Size must be between ${MIN_GB} and ${MAX_GB} GB.` };
76	  }
77	
78	  const priceCents = await volumePriceCents(size);
79	
80	  let volumeId: string;
81	  try {
82	    volumeId = await db.$transaction(async (tx) => {
83	      await debitWallet(tx, user.id, priceCents);
84	      await tx.walletTransaction.create({
85	        data: {
86	          userId: user.id,
87	          amountCents: -priceCents,
88	          description: `Block storage volume: ${clean} (${size} GB)`,
89	        },
90	      });
91	      const v = await tx.volume.create({
92	        data: {
93	          userId: user.id,
94	          name: clean,
95	          sizeGB: size,
96	          priceCents,
97	          status: "PENDING",
98	          expiresAt: addMonths(new Date(), 1),
99	        },
100	      });
101	      await tx.job.create({ data: { type: "VOLUME_CREATE", payload: { volumeId: v.id } } });
102	      return v.id;
103	    });
104	  } catch (e) {
105	    if (e instanceof InsufficientBalanceError) {
106	      return { error: "Insufficient balance — top up your wallet first." };
107	    }
108	    throw e;
109	  }
110	
111	  await db.auditLog.create({
112	    data: { userId: user.id, action: "volume.order", detail: `${volumeId} ${clean} ${size}GB` },
113	  });
114	  revalidatePath("/dashboard/volumes");
115	  return { id: volumeId };
116	}
117	
118	/** Attach a DETACHED volume to one of the caller's RUNNING servers. */
119	export async function attachVolume(
120	  volumeId: string,
121	  serverId: string
122	): Promise<{ error?: string }> {
123	  const { user, volume } = await ownedVolume(volumeId);
124	  const { server } = await ownedServer(serverId);
125	
126	  if (volume.status !== "DETACHED") {
127	    return { error: "Only an available (detached) volume can be attached." };
128	  }
129	  if (!server.vmid || server.status !== "RUNNING") {
130	    return { error: "Target server must be running." };
131	  }
132	  // A volume that already holds data physically lives on one server's VM; it can
133	  // only be re-attached there (cross-node disk migration is out of scope).
134	  if (volume.serverId && volume.serverId !== serverId) {
135	    return { error: "This volume holds data on another server. Attach it there, or delete it first." };
136	  }
137	  if (await serverBusy(serverId)) {
138	    return { error: "Another operation is already in progress on this server." };
139	  }
140	
141	  await db.volume.update({ where: { id: volumeId }, data: { serverId } });
142	  await db.job.create({ data: { type: "VOLUME_ATTACH", serverId, payload: { volumeId } } });
143	  await db.auditLog.create({
144	    data: { userId: user.id, action: "volume.attach", detail: `${volumeId} -> ${serverId}` },
145	  });
146	  revalidatePath("/dashboard/volumes");
147	  revalidatePath(`/dashboard/servers/${serverId}`);
148	  return {};
149	}
150	
151	/** Detach an ATTACHED volume from its server (data is preserved as an unused disk). */
152	export async function detachVolume(volumeId: string): Promise<{ error?: string }> {
153	  const { user, volume } = await ownedVolume(volumeId);
154	  if (volume.status !== "ATTACHED" || !volume.serverId) {
155	    return { error: "Volume is not attached." };
156	  }
157	  if (await serverBusy(volume.serverId)) {
158	    return { error: "Another operation is already in progress on this server." };
159	  }
160	  await db.job.create({
161	    data: { type: "VOLUME_DETACH", serverId: volume.serverId, payload: { volumeId } },
162	  });
163	  await db.auditLog.create({
164	    data: { userId: user.id, action: "volume.detach", detail: `${volumeId}` },
165	  });
166	  revalidatePath("/dashboard/volumes");
167	  revalidatePath(`/dashboard/servers/${volume.serverId}`);
168	  return {};
169	}
170	
171	/** Permanently delete a volume: detaches + destroys the disk, then removes the row. */
172	export async function deleteVolume(volumeId: string): Promise<{ error?: string }> {
173	  const { user, volume } = await ownedVolume(volumeId);
174	  if (volume.status === "DELETING") return { error: "Volume is already being deleted." };
175	
176	  // If the disk physically lives on a server, route the delete through it and
177	  // honour the one-in-flight-job guard so we don't collide with another op.
178	  if (volume.serverId) {
179	    if (await serverBusy(volume.serverId)) {
180	      return { error: "Another operation is already in progress on this server." };
181	    }
182	  }
183	  await db.volume.update({ where: { id: volumeId }, data: { status: "DELETING" } });
184	  await db.job.create({
185	    data: {
186	      type: "VOLUME_DELETE",
187	      serverId: volume.serverId ?? undefined,
188	      payload: { volumeId },
189	    },
190	  });
191	  await db.auditLog.create({
192	    data: { userId: user.id, action: "volume.delete", detail: `${volumeId}` },
193	  });
194	  revalidatePath("/dashboard/volumes");
195	  if (volume.serverId) revalidatePath(`/dashboard/servers/${volume.serverId}`);
196	  return {};
197	}
