93	export async function purchaseDomain(prev: any, formData: FormData): Promise<{ error?: string }> {
94	  const user = await requireUser();
95	  // Purchase gate: an unverified address means we cannot reach the person we
96	  // are about to charge. See lib/email-verification.ts.
97	  const unverified = await emailVerificationError(user);
98	  if (unverified) return { error: unverified };
99	  // Feature flag: domain registration can be switched off platform-wide.
100	  if (!(await getSettingBool("feature_domains", true))) {
101	    return { error: "Domain registration is currently unavailable." };
102	  }
103	  if (!registrarConfigured()) {
104	    return { error: "Domain registration is not configured yet (name.com API keys missing)." };
105	  }
106	  const contactSchema = z.object({
107	    firstName: z.string().min(1).max(60),
108	    lastName: z.string().min(1).max(60),
109	    address1: z.string().min(1).max(120),
110	    city: z.string().min(1).max(60),
111	    stateProvince: z.string().min(1).max(60),
112	    postalCode: z.string().min(1).max(20),
113	    country: z.string().length(2),
114	    phone: z.string().regex(/^\+\d{1,3}\.\d{4,14}$/, "Phone format: +1.5551234567"),
115	    email: z.string().email(),
116	  });
117	  const domain = String(formData.get("domain") ?? "").toLowerCase().trim();
118	  if (!DOMAIN_RE.test(domain)) return { error: "Invalid domain name." };
119	  const dTerm = domainTerm(Number(formData.get("years") ?? 1));
120	
121	  const contactParsed = contactSchema.safeParse({
122	    firstName: formData.get("firstName"),
123	    lastName: formData.get("lastName"),
124	    address1: formData.get("address1"),
125	    city: formData.get("city"),
126	    stateProvince: formData.get("stateProvince"),
127	    postalCode: formData.get("postalCode"),
128	    country: String(formData.get("country") ?? "").toUpperCase(),
129	    phone: formData.get("phone"),
130	    email: formData.get("email"),
131	  });
132	  if (!contactParsed.success) {
133	    return { error: contactParsed.error.issues[0]?.message ?? "Invalid registrant contact." };
134	  }
135	
136	  // Short-window duplicate-submit guard (double-click / retry-after-timeout).
137	  const guardKey = `register:${user.id}:${domain}`;
138	  if (!beginSubmit(guardKey)) {
139	    return { error: "That registration is already being processed — give it a moment before retrying." };
140	  }
141	
142	  try {
143	    const existing = await db.domain.findUnique({ where: { name: domain } });
144	    if (existing) {
145	      if (existing.userId !== user.id) return { error: "This domain is already managed by another account." };
146	      if (existing.status === "PENDING") {
147	        return { error: "You already have a registration in progress for this domain." };
148	      }
149	      return { error: `You already have ${domain} on this account (status: ${existing.status.toLowerCase()}).` };
150	    }
151	
152	    // Live availability + retail(markup) & cost prices from name.com
153	    let priceCents: number; // retail per year (customer)
154	    let costCents: number; // registrar cost per year (us)
155	    try {
156	      const [check] = await checkDomains([domain]);
157	      if (!check) return { error: "Could not check availability. Try again." };
158	      if (!check.available) return { error: "Domain is not available." };
159	      if (check.premium) return { error: "Premium domains are not supported yet." };
160	      if (check.priceCents === null || check.costCents === null) return { error: "No price available for this TLD." };
161	      priceCents = check.priceCents;
162	      costCents = check.costCents;
163	    } catch (e: any) {
164	      return { error: String(e?.message ?? e).slice(0, 200) };
165	    }
166	
167	    const totalCents = domainTermPriceCents(priceCents, dTerm.years); // customer pays (retail, term-discounted)
168	    const registrarCostCents = costCents * dTerm.years; // we pay name.com the true cost
169	    if (user.balanceCents < totalCents) {
170	      return { error: `Insufficient balance — ${dTerm.label} costs $${(totalCents / 100).toFixed(2)}.` };
171	    }
172	
173	    let record;
174	    try {
175	      record = await db.$transaction(async (tx) => {
176	        // Re-check inside the transaction: the availability round-trip above is
177	        // slow enough for a second submit to slip in. `Domain.name` is UNIQUE, so
178	        // even if this read misses, the create below rolls the whole debit back.
179	        const dupe = await tx.domain.findUnique({ where: { name: domain }, select: { id: true } });
180	        if (dupe) throw new DuplicateDomainError();
181	        await debitWallet(tx, user.id, totalCents);
182	        await tx.walletTransaction.create({
183	          data: { userId: user.id, amountCents: -totalCents, description: `Domain registration: ${domain} (${dTerm.label})` },
184	        });
185	        return tx.domain.create({
186	          data: { name: domain, userId: user.id, priceCents, costCents, termYears: dTerm.years, status: "PENDING", registrar: "name.com" },
187	        });
188	      });
189	    } catch (e) {
190	      if (e instanceof InsufficientBalanceError) return { error: "Insufficient balance — top up your wallet first." };
191	      if (e instanceof DuplicateDomainError || isUniqueConflict(e)) {
192	        return { error: "This domain is already being registered — you have not been charged twice." };
193	      }
194	      throw e;
195	    }
196	
197	    try {
198	      const { expiresAt } = await registerDomain(domain, dTerm.years, contactParsed.data as RegistrantContact, registrarCostCents);
199	      const info = expiresAt ? { expires: expiresAt } : await domainInfo(domain).catch(() => ({ expires: undefined }));
200	      await db.domain.update({
201	        where: { id: record.id },
202	        data: {
203	          status: "ACTIVE",
204	          registeredAt: new Date(),
205	          expiresAt: info.expires ?? new Date(Date.now() + dTerm.years * 365 * 86400_000),
206	        },
207	      });
208	      await db.auditLog.create({ data: { userId: user.id, action: "domain.register", detail: `${domain} ${dTerm.years}yr` } });
209	      await db.notification.create({
210	        data: { userId: user.id, title: `Domain registered: ${domain}`, href: `/dashboard/domains/${record.id}` },
211	      });
212	    } catch (e: any) {
213	      const reason = String(e?.message ?? e).slice(0, 400);
214	      // NEVER refund blind: a timeout/5xx often means the order DID go through.
215	      const verdict = await verifyRegistration(domain);
216	
217	      if (verdict.state === "registered") {
218	        // The registration exists — keep the charge and finish the record.
219	        await db.domain.update({
220	          where: { id: record.id },
221	          data: {
222	            status: "ACTIVE",
223	            registeredAt: new Date(),
224	            expiresAt: verdict.expires ?? new Date(Date.now() + dTerm.years * 365 * 86400_000),
225	            error: `Recovered after registrar error: ${reason}`.slice(0, 500),
226	          },
227	        });
228	        await db.auditLog.create({
229	          data: { userId: user.id, action: "domain.register.recovered", detail: `${domain}: ${reason}`.slice(0, 500) },
230	        });
231	        await db.notification.create({
232	          data: { userId: user.id, title: `Domain registered: ${domain}`, href: `/dashboard/domains/${record.id}` },
233	        });
234	        redirect(`/dashboard/domains/${record.id}`);
235	      }
236	
237	      if (verdict.state === "not-registered") {
238	        // Confirmed still available at the registrar — refunding is safe.
239	        await db.$transaction([
240	          db.user.update({ where: { id: user.id }, data: { balanceCents: { increment: totalCents } } }),
241	          db.walletTransaction.create({
242	            data: { userId: user.id, amountCents: totalCents, description: `Refund: failed registration ${domain}` },
243	          }),
244	          db.domain.update({
245	            where: { id: record.id },
246	            data: { status: "FAILED", error: reason.slice(0, 500) },
247	          }),
248	        ]);
249	        return { error: `Registration failed: ${reason.slice(0, 200)} (you were refunded).` };
250	      }
251	
252	      // Unknown: leave PENDING and charged, flag for manual review. Refunding
253	      // here risks giving away a domain we actually paid the registrar for.
254	      await db.domain.update({
255	        where: { id: record.id },
256	        data: { status: "PENDING", error: `NEEDS REVIEW — registrar status unconfirmed: ${reason}`.slice(0, 500) },
257	      });
258	      await db.auditLog.create({
259	        data: { userId: user.id, action: "domain.register.needs_review", detail: `${domain}: ${reason}`.slice(0, 500) },
260	      });
261	      await db.notification.create({
262	        data: {
263	          userId: user.id,
264	          title: `Domain ${domain} needs review`,
265	          body: "We could not confirm the registration with the registrar. Our team is checking it — no duplicate charge will be made.",
266	          href: `/dashboard/domains/${record.id}`,
267	        },
268	      });
269	      return {
270	        error:
271	          `We could not confirm ${domain} with the registrar (${reason.slice(0, 120)}). ` +
272	          `It is marked for review — do not retry, you will not be charged twice.`,
273	      };
274	    }
275	    redirect(`/dashboard/domains/${record.id}`);
276	  } finally {
277	    endSubmit(guardKey);
278	  }
279	}
