281	/** A renewal already landed if the registrar expiry runs ~a month past ours. */
282	const RENEW_SLACK_MS = 30 * 86400_000;
283	
284	export async function renewDomainAction(domainId: string): Promise<{ error?: string }> {
285	  const user = await requireUser();
286	  // Purchase gate: a MANUAL renewal is a fresh spend decision. Automatic domain
287	  // renewal runs in the worker and does not come through here, so no existing
288	  // domain can lapse because of this check.
289	  const unverifiedRenew = await emailVerificationError(user);
290	  if (unverifiedRenew) return { error: unverifiedRenew };
291	  const domain = await db.domain.findUnique({ where: { id: domainId } });
292	  if (!domain || (domain.userId !== user.id && user.role !== "ADMIN")) return { error: "Not found." };
293	  if (domain.status === "PENDING") return { error: "This domain's registration is still being confirmed." };
294	  if (domain.status === "FAILED") return { error: "This domain is not registered." };
295	
296	  // Short-window duplicate-submit guard (double-click / retry-after-timeout).
297	  const guardKey = `renew:${domain.userId}:${domain.name}`;
298	  if (!beginSubmit(guardKey)) {
299	    return { error: "A renewal for this domain is already in progress." };
300	  }
301	
302	  try {
303	    const dTerm = domainTerm(domain.termYears);
304	    const renewCents = domainTermPriceCents(domain.priceCents, dTerm.years);
305	    const owner = await db.user.findUnique({ where: { id: domain.userId } });
306	    if (!owner || owner.balanceCents < renewCents) return { error: "Insufficient balance." };
307	
308	    const dbExpiry = domain.expiresAt ?? null;
309	
310	    // Idempotency: charge and expiry advance together in one transaction below,
311	    // so if the registrar expiry is already ahead of ours a previous attempt
312	    // renewed but never got charged/recorded. Adopt that renewal instead of
313	    // buying a second year.
314	    let registrarExpiry: Date | undefined;
315	    try {
316	      registrarExpiry = (await domainInfo(domain.name)).expires;
317	    } catch {
318	      /* non-fatal: fall through to a normal renew */
319	    }
320	    const alreadyRenewed =
321	      !!registrarExpiry && !!dbExpiry && registrarExpiry.getTime() > dbExpiry.getTime() + RENEW_SLACK_MS;
322	
323	    if (!alreadyRenewed) {
324	      try {
325	        await renewDomain(domain.name, dTerm.years, (domain.costCents || domain.priceCents) * dTerm.years);
326	      } catch (e: any) {
327	        return { error: `Renewal failed: ${String(e?.message ?? e).slice(0, 200)}` };
328	      }
329	      registrarExpiry = await domainInfo(domain.name)
330	        .then((i) => i.expires)
331	        .catch(() => undefined);
332	    }
333	
334	    const targetExpiry =
335	      registrarExpiry ?? new Date((dbExpiry ?? new Date()).getTime() + dTerm.years * 365 * 86400_000);
336	
337	    try {
338	      const charged = await db.$transaction(async (tx) => {
339	        // Re-read under the transaction: if a concurrent request already advanced
340	        // the expiry it also already took the money — do not charge again.
341	        const fresh = await tx.domain.findUnique({ where: { id: domainId }, select: { expiresAt: true } });
342	        if (dbExpiry && fresh?.expiresAt && fresh.expiresAt.getTime() > dbExpiry.getTime() + RENEW_SLACK_MS) {
343	          return false;
344	        }
345	        await debitWallet(tx, domain.userId, renewCents);
346	        await tx.walletTransaction.create({
347	          data: { userId: domain.userId, amountCents: -renewCents, description: `Domain renewal: ${domain.name} (${dTerm.label})` },
348	        });
349	        await tx.domain.update({
350	          where: { id: domainId },
351	          data: { expiresAt: targetExpiry, status: "ACTIVE" },
352	        });
353	        return true;
354	      });
355	      if (!charged) {
356	        revalidatePath(`/dashboard/domains/${domainId}`);
357	        return {};
358	      }
359	    } catch (e) {
360	      if (e instanceof InsufficientBalanceError) {
361	        // The registrar renewal already succeeded — flag the uncollected charge
362	        // instead of silently swallowing it.
363	        await db.auditLog
364	          .create({
365	            data: {
366	              userId: domain.userId,
367	              action: "domain.renew.uncharged",
368	              detail: `${domain.name}: renewed at registrar but wallet debit of ${renewCents}c failed`,
369	            },
370	          })
371	          .catch(() => {});
372	        return { error: "Insufficient balance." };
373	      }
374	      throw e;
375	    }
376	    revalidatePath(`/dashboard/domains/${domainId}`);
377	    return {};
378	  } finally {
379	    endSubmit(guardKey);
380	  }
381	}
