403	export async function addDnsRecord(prev: any, formData: FormData): Promise<{ error?: string }> {
404	  const domainId = String(formData.get("domainId") ?? "");
405	  let ctx;
406	  try {
407	    ctx = await ownedDomain(domainId);
408	  } catch (e: any) {
409	    return { error: e.message };
410	  }
411	  const parsed = z
412	    .object({
413	      name: z.string().max(120).default(""),
414	      type: z.enum(RECORD_TYPES),
415	      address: z.string().min(1).max(500),
416	      ttl: z.coerce.number().int().min(60).max(86400).default(300),
417	      mxPref: z.coerce.number().int().min(0).max(65535).optional(),
418	    })
419	    .safeParse({
420	      name: formData.get("name") ?? "",
421	      type: formData.get("type"),
422	      address: formData.get("address"),
423	      ttl: formData.get("ttl") || 300,
424	      mxPref: formData.get("mxPref") || undefined,
425	    });
426	  if (!parsed.success) return { error: parsed.error.issues[0]?.message ?? "Invalid record." };
427	
428	  // "@" or blank => apex (name.com uses empty host for apex)
429	  const host = ["@", ""].includes(parsed.data.name.trim()) ? "" : parsed.data.name.trim();
430	  try {
431	    await addRecord(ctx.domain.name, {
432	      host,
433	      type: parsed.data.type,
434	      answer: parsed.data.address,
435	      ttl: parsed.data.ttl,
436	      priority: parsed.data.type === "MX" || parsed.data.type === "SRV" ? parsed.data.mxPref ?? 10 : undefined,
437	    });
438	  } catch (e: any) {
439	    return { error: String(e?.message ?? e).slice(0, 200) };
440	  }
441	  revalidatePath(`/dashboard/domains/${domainId}`);
442	  return {};
443	}
