445	export async function deleteDnsRecord(
446	  domainId: string,
447	  record: { name: string; type: string; address: string }
448	): Promise<{ error?: string }> {
449	  let ctx;
450	  try {
451	    ctx = await ownedDomain(domainId);
452	  } catch (e: any) {
453	    return { error: e.message };
454	  }
455	  const wantHost = ["@", ""].includes(record.name) ? "" : record.name;
456	  try {
457	    const recs = await listRecords(ctx.domain.name);
