459	    if (!match) return { error: "Record not found (it may have already been removed)." };
460	    await deleteRecord(ctx.domain.name, match.id);
461	  } catch (e: any) {
462	    return { error: String(e?.message ?? e).slice(0, 200) };
463	  }
464	  revalidatePath(`/dashboard/domains/${domainId}`);
465	  return {};
466	}
