468	/** One-click: point apex + www at the platform's public IP. */
469	export async function pointDomainAtServer(domainId: string): Promise<{ error?: string }> {
470	  let ctx;
471	  try {
472	    ctx = await ownedDomain(domainId);
473	  } catch (e: any) {
474	    return { error: e.message };
475	  }
476	  const ip = process.env.PUBLIC_IP;
477	  if (!ip) return { error: "Public IP not configured." };
478	  try {
479	    const recs = await listRecords(ctx.domain.name);
480	    for (const r of recs) {
481	      if (["", "www"].includes(r.host) && r.type === "A") await deleteRecord(ctx.domain.name, r.id);
482	    }
483	    await addRecord(ctx.domain.name, { host: "", type: "A", answer: ip, ttl: 300 });
484	    await addRecord(ctx.domain.name, { host: "www", type: "A", answer: ip, ttl: 300 });
485	  } catch (e: any) {
486	    return { error: String(e?.message ?? e).slice(0, 200) };
487	  }
488	  revalidatePath(`/dashboard/domains/${domainId}`);
489	  return {};
490	}
