51	export async function adminSaveGamePlan(prev: Result | undefined, formData: FormData): Promise<Result> {
52	  const admin = await requireArea("billing");
53	
54	  const rawSlots = String(formData.get("slots") ?? "").trim();
55	  const rawOs = String(formData.get("osTemplateId") ?? "").trim();
56	  const parsed = planSchema.safeParse({
57	    id: formData.get("id") || undefined,
58	    gameFamily: formData.get("gameFamily"),
59	    name: formData.get("name"),
60	    ramMB: formData.get("ramMB"),
61	    cpuCores: formData.get("cpuCores"),
62	    diskGB: formData.get("diskGB"),
63	    slots: rawSlots === "" ? undefined : rawSlots,
64	    priceCents: formData.get("priceCents"),
65	    termMonths: formData.get("termMonths"),
66	    basePlanId: formData.get("basePlanId"),
67	    osTemplateId: rawOs === "" ? undefined : rawOs,
68	    sortOrder: formData.get("sortOrder") ?? 0,
69	  });
70	  if (!parsed.success) {
71	    return { error: parsed.error.issues[0]?.message ?? "Check the tier values." };
72	  }
73	  const d = parsed.data;
74	
75	  const base = await db.plan.findUnique({ where: { id: d.basePlanId } });
