95	    cpuCores: d.cpuCores,
96	    diskGB: d.diskGB,
97	    slots: d.slots ?? null,
98	    priceCents: d.priceCents,
99	    termMonths: d.termMonths,
100	    basePlanId: d.basePlanId,
