119	      detail: `${data.gameFamily} — ${data.name} (${(data.priceCents / 100).toFixed(2)}/${data.termMonths}mo)`,
120	    },
121	  });
122	  revalidatePath("/admin/game-plans");
123	  return { ok: true };
124	}
