164	/**
165	 * Order a game server from a GamePlan tier. Mirrors lib/actions.ts orderServer:
166	 * validate the tier, atomically debit the wallet for `gamePlan.priceCents`, then
167	 * create the Server (sized by the tier's base VPS plan, running the game image)
168	 * plus a PROVISION Job in one transaction. Redirects to the new server.
169	 */
170	export async function orderGameServer(gamePlanId: string): Promise<Result> {
171	  const user = await requireUser();
172	  // Purchase gate: an unverified address means we cannot reach the person we
173	  // are about to charge. See lib/email-verification.ts.
174	  const unverified = await emailVerificationError(user);
175	  if (unverified) return { error: unverified };
176	
177	  // Feature flag: game servers can be switched off platform-wide.
178	  if (!(await getSettingBool("feature_game_servers", true))) {
179	    return { error: "Game servers aren't available right now." };
180	  }
181	
182	  // Game servers are Server rows too, so they count toward the per-user cap
183	  // (`max_servers_per_user`, default 10; 0 = unlimited).
184	  const cap = await getSettingInt("max_servers_per_user", 10);
185	  if (cap > 0) {
186	    const owned = await db.server.count({ where: { userId: user.id, status: { notIn: ["DELETING"] } } });
187	    if (owned >= cap) {
188	      return { error: `You've reached your limit of ${cap} server${cap === 1 ? "" : "s"}.` };
189	    }
190	  }
191	
192	  const gp = await db.gamePlan.findUnique({
193	    where: { id: gamePlanId },
194	    include: { basePlan: true },
195	  });
196	  if (!gp || !gp.active) return { error: "That game plan isn't available." };
197	  if (!gp.basePlan?.active) return { error: "Provisioning is temporarily unavailable for this game." };
198	  if (!GAME_FAMILIES.includes(gp.gameFamily as GameFamily)) {
199	    return { error: "Unknown game family." };
200	  }
201	
202	  // Resolve the game image: the tier's own OsTemplate, else any active image for
203	  // this game family. A game server can't provision without an image.
204	  let osTemplateId = gp.osTemplateId;
205	  if (osTemplateId) {
206	    const os = await db.osTemplate.findUnique({ where: { id: osTemplateId } });
207	    if (!os?.active) osTemplateId = null;
208	  }
209	  if (!osTemplateId) {
210	    const os = await db.osTemplate.findFirst({
211	      where: { family: gp.gameFamily, category: "APPLICATION", active: true },
212	      orderBy: { sortOrder: "asc" },
213	    });
214	    if (!os) return { error: "No game image is configured for this game yet." };
215	    osTemplateId = os.id;
216	  }
217	
218	  const chargeCents = gp.priceCents;
219	  if (user.balanceCents < chargeCents) {
220	    return { error: "Insufficient balance. Top up your wallet first." };
221	  }
222	
223	  // Oversell guard — the VPS order path enforces this but game orders skipped it,
224	  // letting game servers commit host RAM past capacity. Check the base plan's
225	  // footprint before charging or enqueuing a PROVISION that can't be scheduled.
226	  const capacity = await capacityCheck(gp.basePlanId);
227	  if (!capacity.ok) return { error: capacity.reason ?? "The host is at capacity right now. Please try again shortly." };
228	
229	  const hostname = `${gp.gameFamily}-${rand()}`;
230	
231	  let server;
232	  try {
233	    server = await db.$transaction(async (tx) => {
234	      await debitWallet(tx, user.id, chargeCents);
235	      await tx.walletTransaction.create({
236	        data: {
237	          userId: user.id,
238	          amountCents: -chargeCents,
239	          description: `Game server: ${gp.name} (${gp.gameFamily})`,
240	        },
241	      });
242	      const s = await tx.server.create({
243	        data: {
244	          name: hostname,
245	          hostname,
246	          userId: user.id,
247	          planId: gp.basePlanId,
248	          gamePlanId: gp.id,
249	          osTemplateId: osTemplateId!,
250	          termMonths: gp.termMonths,
251	          // A game plan is a flat all-in price: `chargeCents` above is
252	          // `gp.priceCents` with no term discount and no seasonal promo applied, and
253	          // renewalCharge (lib/stripe-cards.ts) renews it at that same flat price.
254	          // So this term was sold at 0% off — full price — and any proration must
255	          // price against that, not against whatever promo is running later.
256	          termPromoPercent: 0,
257	          wantsDedicatedIp: false,
258	          expiresAt: addMonths(new Date(), gp.termMonths),
259	        },
260	      });
261	      await tx.job.create({ data: { type: "PROVISION", serverId: s.id } });
262	      return s;
263	    });
264	  } catch (e) {
265	    if (e instanceof InsufficientBalanceError) {
266	      return { error: "Insufficient balance. Top up your wallet first." };
267	    }
268	    throw e;
269	  }
270	
271	  await db.auditLog.create({
272	    data: {
273	      userId: user.id,
274	      action: "gameserver.order",
275	      detail: `${server.id} game=${gp.gameFamily} tier=${gp.name}`,
276	    },
277	  });
278	  redirect(`/dashboard/servers/${server.id}`);
279	}
