41	/**
42	 * Compute the extra wallet credit a coupon grants for a top-up of `baseCents`.
43	 * PERCENT -> baseCents * value%; CREDIT_CENTS -> flat `value` cents.
44	 *
45	 * FIXED_CENTS returns 0 and is refused before it ever reaches here — see the
46	 * guard in `applyCouponToTopup`. It used to return `coupon.value` as a *bonus*,
47	 * which turned a coupon the admin UI advertises as "$5.00 off" into $5.00 of free
48	 * balance. Kept at 0 so that if the guard is ever removed the failure mode is "no
49	 * bonus", not "mints money".
50	 */
51	function couponBonusForTopup(coupon: Coupon, baseCents: number): number {
52	  switch (coupon.kind) {
53	    case "PERCENT":
54	      return Math.round((baseCents * coupon.value) / 100);
55	    case "CREDIT_CENTS":
56	      return coupon.value;
57	    default:
58	      return 0;
59	  }
60	}
