62	/**
63	 * Is a top-up promo code redeemable AT ALL right now?
64	 *
65	 * This mirrors, deliberately, the two guards at the top of `topUp`
66	 * (lib/actions.ts): the demo gateway is the ONLY code path in the product that
67	 * reads the `nxeon_coupon` cookie and grants the bonus, and it refuses when
68	 * NODE_ENV is production or when Stripe is configured. The real card path
69	 * (app/api/stripe/checkout/route.ts -> `creditCheckoutSession`) credits
70	 * `session.amount_total` verbatim, so it cannot add a bonus on top of what was
71	 * charged — no amount of work in this file changes that.
72	 *
73	 * So when this returns false a promo code cannot be honoured by anything, and
74	 * accepting one would reproduce the exact defect this codebase keeps shipping: a
75	 * green "Code applied" that is read by nothing (compare the auto-suspend kill
76	 * switch, and the domain markup that displayed 0% while charging 25%).
77	 *
78	 * TO TURN COUPONS BACK ON, one change is needed in a file this change does not
79	 * own — `lib/fulfil-checkout.ts`, in its `kind: "topup"` branch:
80	 *
81	 *   1. `app/api/stripe/checkout/route.ts` re-validates the cookie's code against
82	 *      the REAL amount and stamps `nxeonCoupon: JSON.stringify({ couponId,
83	 *      bonusCents })` into the session metadata. Computing the bonus once, at
84	 *      session creation, against the amount the customer is actually charged is
85	 *      what makes "never charge more than displayed" hold — the $25 preview
86	 *      amount must never be what gets paid out.
87	 *   2. `fulfilCheckoutSession` calls `claim(sessionId, "topup")` — which it does
88	 *      not do today, because a plain top-up needs no fulfilment — and grants the
89	 *      bonus only if it wins the claim.
90	 *   3. The grant is one `$transaction`: increment `balanceCents`, insert the
91	 *      `WalletTransaction`, insert the `CouponRedemption`, increment
92	 *      `Coupon.timesRedeemed`.
93	 *
94	 * That gives THREE independent stops against a replayed webhook paying twice: the
95	 * UNIQUE `FulfilledSession.stripeSessionId` claim, the
96	 * `@@unique([couponId, userId])` on `CouponRedemption`, and metadata that fixes
97	 * the bonus to one session. Any one of them alone is sufficient; the redemption
98	 * constraint is the one that also survives a session being replaced.
99	 *
100	 * Once the bonus is granted there, replace the body of this function with
101	 * `return true`.
102	 */
103	async function topupCouponRedeemable(): Promise<boolean> {
104	  const { stripeConfigured } = await import("./stripe");
105	  return process.env.NODE_ENV !== "production" && !stripeConfigured();
106	}
