108	/**
109	 * Validate a promo code for the CURRENT user against a top-up of `baseCents` and
110	 * return the bonus that would be credited. Read-only: it never mutates state,
111	 * so it is safe to call both for the live preview (CouponField) and again inside
112	 * `topUp` to compute the real bonus. Enforces redeemability / active / expiry /
113	 * scope / kind / minAmount / maxRedemptions / firstTimeOnly / one-per-user rules.
114	 *
115	 * Every `ok: false` here carries a reason the customer can read. That matters
116	 * because a caller may use `ok: true` as a promise: `CouponField` renders a green
117	 * "Code applied" from it, so this function must never say yes to something the
118	 * money path will not honour.
119	 */
120	export async function applyCouponToTopup(
121	  code: string,
122	  baseCents: number
123	): Promise<CouponApplyResult> {
124	  const user = await requireUser();
125	  // Global kill-switch: when coupons are disabled no code may be redeemed.
126	  // Checked here so both the live preview and the real `topUp` apply are covered.
127	  if (!(await getSettingBool("coupons_enabled", true))) {
128	    return { ok: false, error: "Promo codes are currently disabled." };
129	  }
130	  // Honesty gate. Refuse BEFORE looking the code up, so we neither promise a
131	  // bonus no code path can grant nor leak which codes exist. See
132	  // `topupCouponRedeemable` for the single change that lifts this.
133	  if (!(await topupCouponRedeemable())) {
134	    return {
135	      ok: false,
136	      error:
137	        "Promo codes can’t be applied to card payments yet, so this code has not been applied — nothing has been charged. Contact support if you were given this code.",
138	    };
139	  }
140	  const normalized = String(code ?? "").trim().toUpperCase();
141	  if (!normalized) return { ok: false, error: "Enter a promo code." };
142	
143	  const coupon = await db.coupon.findUnique({ where: { code: normalized } });
144	  if (!coupon || !coupon.active) return { ok: false, error: "That code isn’t valid." };
145	  if (coupon.scope === "ORDER") {
146	    return { ok: false, error: "This code only applies to server orders." };
147	  }
148	  // "Fixed cents off" is a DISCOUNT, and a wallet top-up has nothing to discount:
149	  // the customer names the amount and pays exactly that. This kind used to be
150	  // handed to `couponBonusForTopup` and paid out as a bonus, so a coupon that
151	  // /admin/coupons renders as "$5.00 off" credited the customer $5.00 of free
152	  // balance instead (QA-PRELAUNCH P1-7). Refuse it rather than silently
153	  // reinterpret an admin's intent as its opposite.
154	  if (coupon.kind === "FIXED_CENTS") {
155	    return {
156	      ok: false,
157	      error: "This code is money off an order, not top-up credit — it can’t be used here.",
158	    };
159	  }
160	  if (coupon.expiresAt && coupon.expiresAt.getTime() < Date.now()) {
161	    return { ok: false, error: "This code has expired." };
162	  }
163	  if (coupon.maxRedemptions !== null && coupon.timesRedeemed >= coupon.maxRedemptions) {
164	    return { ok: false, error: "This code has reached its redemption limit." };
165	  }
166	  if (coupon.minAmountCents !== null && baseCents < coupon.minAmountCents) {
167	    return {
168	      ok: false,
169	      error: `Add at least $${(coupon.minAmountCents / 100).toFixed(2)} to use this code.`,
170	    };
171	  }
172	
173	  // One redemption per user (mirrors the @@unique([couponId,userId]) constraint).
174	  const already = await db.couponRedemption.findUnique({
175	    where: { couponId_userId: { couponId: coupon.id, userId: user.id } },
176	  });
177	  if (already) return { ok: false, error: "You’ve already used this code." };
178	
179	  if (coupon.firstTimeOnly) {
180	    // "First-time" = the user has never received a positive wallet credit before.
181	    const priorCredits = await db.walletTransaction.count({
182	      where: { userId: user.id, amountCents: { gt: 0 } },
183	    });
184	    if (priorCredits > 0) {
185	      return { ok: false, error: "This code is for first-time customers only." };
186	    }
187	  }
188	
189	  const bonusCents = Math.max(0, couponBonusForTopup(coupon, baseCents));
190	  return {
191	    ok: true,
192	    couponId: coupon.id,
193	    code: coupon.code,
194	    bonusCents,
195	    label: describeCoupon(coupon),
196	  };
197	}
