222	  const admin = await requireAdmin();
223	  const rawExpires = String(formData.get("expiresAt") ?? "").trim();
224	  const rawMin = String(formData.get("minAmountCents") ?? "").trim();
225	  const rawMax = String(formData.get("maxRedemptions") ?? "").trim();
226	  const parsed = couponSchema.safeParse({
227	    code: formData.get("code"),
228	    kind: formData.get("kind"),
229	    scope: formData.get("scope"),
230	    value: formData.get("value"),
231	    firstTimeOnly: formData.get("firstTimeOnly") === "on",
232	    minAmountCents: rawMin === "" ? undefined : rawMin,
233	    maxRedemptions: rawMax === "" ? undefined : rawMax,
234	    expiresAt: rawExpires === "" ? undefined : rawExpires,
235	    note: formData.get("note") || undefined,
236	  });
237	  if (!parsed.success) {
238	    return { error: parsed.error.issues[0]?.message ?? "Invalid coupon." };
239	  }
240	  const data = parsed.data;
241	  if (data.kind === "PERCENT" && data.value > 100) {
242	    return { error: "Percent value must be between 1 and 100." };
243	  }
244	  const code = data.code.toUpperCase();
245	
246	  const existing = await db.coupon.findUnique({ where: { code } });
247	  if (existing) return { error: "A coupon with that code already exists." };
