304	/**
305	 * Grant the configured signup free credit to a freshly-registered user, once.
306	 * No-op when SIGNUP_FREE_CREDIT_CENTS is 0 or the user already has signup credit.
307	 * Callable from `register` in lib/actions.ts.
308	 */
309	export async function grantSignupCredit(userId: string): Promise<number> {
310	  await assertInternalGrowthCaller(userId);
311	  // Prefer the admin-editable setting (`signup_free_credit_cents`); fall back to
312	  // the legacy SIGNUP_FREE_CREDIT_CENTS env default when the setting is unset.
313	  const cents = await getSettingInt("signup_free_credit_cents", signupFreeCreditCents());
314	  if (cents <= 0) return 0;
315	  const user = await db.user.findUnique({ where: { id: userId } });
316	  if (!user || user.signupCreditCents > 0) return 0;
317	  await db.$transaction([
318	    db.user.update({
319	      where: { id: userId },
320	      data: { balanceCents: { increment: cents }, signupCreditCents: cents },
321	    }),
322	    db.walletTransaction.create({
323	      data: { userId, amountCents: cents, description: "Welcome credit" },
324	    }),
325	  ]);
326	  return cents;
