329	// ---------- Referral rewards ----------
330	
331	/**
332	 * If `userId` was referred and hasn't been rewarded yet, credit BOTH the referred
333	 * user and their referrer with REFERRAL_REWARD_CENTS, exactly once. Guarded by an
334	 * atomic claim on `referralRewardedAt` so concurrent paid actions can't double-pay.
335	 * Callable from `topUp` / `orderServer` in lib/actions.ts after a paid action.
336	 */
337	export async function maybeRewardReferral(userId: string): Promise<boolean> {
338	  await assertInternalGrowthCaller(userId);
339	  // Feature flag: the referral program can be switched off platform-wide.
340	  if (!(await getSettingBool("feature_referrals", true))) return false;
341	
342	  // Settings → Growth writes `referral_reward_cents` and displays it, but NOTHING
343	  // read it — the payout used the env-backed `referralRewardCents()` instead, so an
344	  // operator changing the reward saw "Saved." and the platform kept paying the old
345	  // amount. Same shape as the domain markup showing 0% while charging 25%, and the
346	  // auto-suspend switch that silenced nothing.
347	  //
348	  // Clamped, and the ceiling matters more here than anywhere else: this reward is
349	  // paid to BOTH the referrer and the referred user, so a stray digit costs twice
350	  // per signup and scales with signup volume. 100_000 cents = $1,000 a side is
351	  // already absurd; anything beyond it is certainly a typo.
352	  const reward = Math.min(
353	    Math.max(await getSettingInt("referral_reward_cents", referralRewardCents()), 0),
354	    100_000
355	  );
356	  if (reward <= 0) return false;
357	
358	  const user = await db.user.findUnique({ where: { id: userId } });
359	  if (!user || !user.referredById || user.referralRewardedAt) return false;
360	  const referrerId = user.referredById;
361	
362	  // Atomically claim the reward; if another concurrent action already did, bail.
363	  const claim = await db.user.updateMany({
364	    where: { id: userId, referralRewardedAt: null, referredById: { not: null } },
365	    data: { referralRewardedAt: new Date() },
366	  });
367	  if (claim.count === 0) return false;
368	
369	  await db.$transaction([
370	    db.user.update({ where: { id: userId }, data: { balanceCents: { increment: reward } } }),
371	    db.walletTransaction.create({
372	      data: { userId, amountCents: reward, description: "Referral bonus — welcome reward" },
373	    }),
374	    db.user.update({ where: { id: referrerId }, data: { balanceCents: { increment: reward } } }),
375	    db.walletTransaction.create({
376	      data: {
377	        userId: referrerId,
378	        amountCents: reward,
379	        description: "Referral bonus — you referred a friend",
380	      },
381	    }),
382	  ]);
383	
384	  // Best-effort in-app notifications, filtered through the notification policy.
385	  //
386	  // `referral_bonus` is ACCOUNT tier, so the in-app bell is never suppressed —
387	  // these rows are the customer's record of money that entered their wallet, and
388	  // hiding a credit would be the same "it silently disappeared" failure the
389	  // preferences exist to cure. The gate is here anyway so the tier in
390	  // `lib/prefs.ts` stays the single decider: if this kind is ever reclassified,
391	  // the filter starts biting without anyone having to remember this call site.
392	  try {
393	    const rows = [
394	      {
395	        userId,
396	        title: `You earned a $${(reward / 100).toFixed(2)} referral bonus`,
397	        href: "/dashboard/billing",
398	      },
399	      {
400	        userId: referrerId,
401	        title: `A friend you referred just joined — $${(reward / 100).toFixed(2)} added`,
402	        href: "/dashboard/refer",
403	      },
404	    ];
405	    const allowed: typeof rows = [];
406	    for (const row of rows) {
407	      if (await mayDeliverTo(row.userId, "referral_bonus", "inapp")) allowed.push(row);
408	    }
409	    if (allowed.length > 0) await db.notification.createMany({ data: allowed });
410	  } catch {
411	    /* best-effort */
412	  }
413	  return true;
414	}
