7	import { debitWallet, InsufficientBalanceError } from "./wallet";
8	import { getSettingBool } from "./settings";
9	import {
10	  MIN_PAYOUT_CENTS,
11	  PAYOUT_STATUSES,
12	  REFERRAL_EARNING_DESCRIPTION,
13	  type PayoutStatus,
14	} from "./affiliate";
15	import { emailVerificationError } from "./email-verification";
16	
17	/** Local sentinel: requested payout exceeds the caller's cashable affiliate balance. */
18	class PayoutExceedsAvailableError extends Error {
19	  availableCents: number;
20	  constructor(availableCents: number) {
21	    super("PAYOUT_EXCEEDS_AVAILABLE");
22	    this.name = "PayoutExceedsAvailableError";
23	    this.availableCents = availableCents;
24	  }
25	}
26	
27	// ---------- Customer: request a payout ----------
28	
29	/**
30	 * Request an affiliate payout for `amountCents`. Model: referral rewards already
31	 * live in the wallet, so a payout CONVERTS wallet credit into a cash-out request —
32	 * it DEBITS the wallet now and records a PENDING AffiliatePayout (admin later marks
33	 * PAID; a DECLINE credits the wallet back). Guards:
34	 *  - integer cents ≥ MIN_PAYOUT_CENTS ($25)
35	 *  - amount ≤ the caller's cashable affiliate balance (unclaimed referral
36	 *    commission, capped by the actual wallet balance), re-read INSIDE the
37	 *    transaction so two concurrent requests can't both pass a stale check.
38	 *  - the wallet debit is an atomic guarded updateMany, so even a race can never
39	 *    drive the balance negative — the second request fails cleanly.
40	 */
41	export async function requestAffiliatePayout(
42	  amountCents: number
43	): Promise<{ ok?: boolean; error?: string }> {
44	  const user = await requireUser();
45	  // Purchase gate: an unverified address means we cannot reach the person we
46	  // are about to charge. See lib/email-verification.ts.
47	  const unverified = await emailVerificationError(user);
48	  if (unverified) return { error: unverified };
49	
50	  // Feature flag: the referral/affiliate program can be switched off platform-wide.
51	  if (!(await getSettingBool("feature_referrals", true))) {
52	    return { error: "The affiliate program is currently unavailable." };
53	  }
54	
55	  const cents = Math.round(Number(amountCents));
56	  if (!Number.isFinite(cents) || cents <= 0) {
57	    return { error: "Enter a valid amount." };
58	  }
59	  if (cents < MIN_PAYOUT_CENTS) {
60	    return { error: `Minimum payout is $${(MIN_PAYOUT_CENTS / 100).toFixed(2)}.` };
61	  }
62	
63	  try {
64	    await db.$transaction(async (tx) => {
65	      // Re-read all state inside the tx to serialize concurrent requests.
66	      const [account, earnedAgg, payouts] = await Promise.all([
67	        tx.user.findUnique({ where: { id: user.id }, select: { balanceCents: true } }),
68	        tx.walletTransaction.aggregate({
69	          _sum: { amountCents: true },
70	          where: { userId: user.id, description: REFERRAL_EARNING_DESCRIPTION },
71	        }),
72	        tx.affiliatePayout.findMany({
73	          where: { userId: user.id, status: { not: "DECLINED" } },
74	          select: { amountCents: true },
75	        }),
76	      ]);
77	      const walletBalanceCents = account?.balanceCents ?? 0;
78	      const totalEarnedCents = earnedAgg._sum.amountCents ?? 0;
79	      const claimedCents = payouts.reduce((s, p) => s + p.amountCents, 0);
80	      const availableCents = Math.max(
81	        0,
82	        Math.min(walletBalanceCents, totalEarnedCents - claimedCents)
83	      );
84	      if (cents > availableCents) throw new PayoutExceedsAvailableError(availableCents);
85	
86	      // Atomic guarded debit — hard-stops any residual race from overdrawing.
87	      await debitWallet(tx, user.id, cents);
88	      await tx.walletTransaction.create({
89	        data: {
90	          userId: user.id,
91	          amountCents: -cents,
92	          description: "Affiliate payout request (wallet cash-out)",
93	        },
94	      });
95	      await tx.affiliatePayout.create({
96	        data: { userId: user.id, amountCents: cents, status: "PENDING" },
97	      });
98	      await tx.auditLog.create({
99	        data: {
100	          userId: user.id,
101	          action: "affiliate.payout_request",
102	          detail: `$${(cents / 100).toFixed(2)}`,
103	        },
104	      });
105	    });
106	  } catch (e) {
107	    if (e instanceof PayoutExceedsAvailableError) {
108	      return { error: `You only have $${(e.availableCents / 100).toFixed(2)} available to withdraw.` };
109	    }
110	    if (e instanceof InsufficientBalanceError) {
111	      return { error: "Insufficient wallet balance for this payout." };
112	    }
113	    throw e;
114	  }
115	
116	  revalidatePath("/dashboard/affiliate");
117	  return { ok: true };
118	}
119	
120	// ---------- Admin: update a payout's status ----------
121	
122	const ALLOWED: readonly PayoutStatus[] = PAYOUT_STATUSES;
123	
124	/**
125	 * Move a payout request to APPROVED / PAID / DECLINED. Money already left the
126	 * wallet when the request was created, so:
127	 *   - PAID     : just stamp `paidAt` (no wallet change — cash was already reserved).
128	 *   - DECLINED : credit the reserved amount back to the wallet (cash-out cancelled).
129	 *   - reactivating a DECLINED payout (back to PENDING/APPROVED/PAID): re-debit it,
130	 *     guarded, so a declined-then-reinstated payout can't be double-spent.
131	 * Billing-area gated. The status change + wallet move are one transaction.
132	 */
133	export async function adminUpdatePayout(
134	  id: string,
135	  status: string
136	): Promise<{ ok?: boolean; error?: string }> {
137	  const admin = await requireArea("billing");
138	
139	  if (!ALLOWED.includes(status as PayoutStatus)) {
140	    return { error: "Invalid status." };
141	  }
142	  const payout = await db.affiliatePayout.findUnique({ where: { id } });
143	  if (!payout) return { error: "Payout not found." };
144	
145	  const wasDeclined = payout.status === "DECLINED";
146	  const willDecline = status === "DECLINED";
147	
148	  try {
149	    await db.$transaction(async (tx) => {
150	      await tx.affiliatePayout.update({
151	        where: { id },
152	        data: {
153	          status,
154	          paidAt: status === "PAID" ? new Date() : null,
155	        },
156	      });
157	      if (willDecline && !wasDeclined) {
158	        // Cancel the cash-out: return the reserved funds to the wallet.
159	        await tx.user.update({
160	          where: { id: payout.userId },
161	          data: { balanceCents: { increment: payout.amountCents } },
162	        });
163	        await tx.walletTransaction.create({
164	          data: {
165	            userId: payout.userId,
166	            amountCents: payout.amountCents,
167	            description: "Affiliate payout declined (funds returned)",
168	          },
169	        });
170	      } else if (!willDecline && wasDeclined) {
171	        // Reinstating a previously-declined payout: re-reserve the funds (guarded).
172	        await debitWallet(tx, payout.userId, payout.amountCents);
173	        await tx.walletTransaction.create({
174	          data: {
175	            userId: payout.userId,
176	            amountCents: -payout.amountCents,
177	            description: "Affiliate payout reinstated (wallet cash-out)",
178	          },
179	        });
180	      }
181	    });
182	  } catch (e) {
183	    if (e instanceof InsufficientBalanceError) {
184	      return { error: "Customer's wallet no longer covers this payout — cannot reinstate." };
185	    }
186	    throw e;
187	  }
188	
189	  await db.auditLog.create({
190	    data: {
191	      userId: admin.id,
192	      action: "affiliate.payout_update",
193	      detail: `${payout.id} → ${status} ($${(payout.amountCents / 100).toFixed(2)})`,
194	    },
195	  });
196	
197	  revalidatePath("/admin/affiliate");
198	  return { ok: true };
199	}
