125	  return typeof p === "string" && p.startsWith("/") && !p.includes("..") && p.length > 1;
126	}
127	
128	/**
129	 * Derive the passwordless lift-and-shift plan from the read-only scan and the set
130	 * of paths the customer chose to copy. Databases are auto-included whenever an
131	 * engine was detected (no password needed — the worker dumps via root's local
132	 * socket/peer auth); Docker/web/runtime prerequisites are inferred so the worker
133	 * can install them on the target. Everything here is secret-free.
134	 */
135	function derivePlan(scan: ScanResult | undefined, selectedPaths: string[]): MigrationPlan {
136	  const empty: MigrationPlan = {
137	    dbEngines: [],
138	    dockerVolumes: [],
139	    composeDirs: [],
140	    verifyPorts: [],
141	    hasContainers: false,
142	    webServers: [],
143	    runtimes: [],
144	  };
145	  if (!scan || !scan.ok) return empty;
146	  const pathSet = new Set(selectedPaths);
147	
148	  // Auto-include every detected engine (dump passwordlessly via root local auth).
149	  const dbEngines = [...new Set((scan.engines ?? []).filter((e) => e.present).map((e) => e.engine))].filter(
150	    (e): e is "mysql" | "postgres" => e === "mysql" || e === "postgres"
151	  );
152	
153	  const containers = scan.containers ?? [];
154	  // Named Docker volumes = container mounts that are NOT absolute host paths.
155	  const dockerVolumes = [
156	    ...new Set(
157	      containers.flatMap((c) => c.mounts ?? []).filter((m) => !isCopyableAbsPath(m) && VOLNAME_RE.test(m))
158	    ),
159	  ].slice(0, 60);
160	
161	  // Compose project dirs among the app dirs the customer is actually copying.
162	  const composeDirs = [
163	    ...new Set((scan.appDirs ?? []).filter((a) => a.signature === "compose" && pathSet.has(a.path)).map((a) => a.path)),
164	  ].slice(0, 40);
165	
166	  // Ports we will hold the migration accountable for. ONLY the customer's own
167	  // services — never the base operating system's.
168	  //
169	  // This used to be every listening port on the source except 22, so a stock
170	  // Debian box handed the customer `25` (exim4, installed by the distro and never
171	  // configured), `5355` (systemd-resolved's mDNS stub) and `53` as "not up on the
172	  // target yet — start the owning app/service". Those are not the customer's
173	  // software, were never part of what they asked to move, and cannot be started
174	  // by them in any meaningful sense. Seven of twenty-two action items in the
175	  // 2026-07-26 rehearsal were this noise, which is how a real action item gets
176	  // lost: a list that cries wolf is a list nobody reads to the end of.
177	  //
178	  // Filtering by PORT NUMBER would be the wrong fix — a customer really can run
179	  // their own mail server on 25. The honest discriminator is the OWNING PROCESS,
180	  // which the scan already captured, so a port is dropped only when the thing
181	  // listening on it is a distro daemon we did not migrate.
182	  const OS_DAEMONS =
183	    /^(systemd-resolve|systemd-resolved|systemd-network|exim4?|sendmail|postfix|rpcbind|rpc\.statd|avahi-daemon|cupsd|chronyd?|ntpd|dhclient|dhcpcd|named|dnsmasq|snapd|multipathd|master)$/i;
184	  const verifyPorts = [
185	    ...new Set(
186	      (scan.ports ?? [])
187	        .filter((p) => {
188	          if (!Number.isInteger(p.port) || p.port < 1 || p.port > 65535 || p.port === 22) return false;
