204	  const procBlob = [
205	    ...(scan.ports ?? []).map((p) => p.proc || ""),
206	    ...(scan.services ?? []).map((s) => s.name || ""),
207	  ]
208	    .join(" ")
209	    .toLowerCase();
210	  const webServers: ("nginx" | "apache")[] = [];
211	  if (/nginx/.test(procBlob)) webServers.push("nginx");
212	  if (/apache|httpd/.test(procBlob)) webServers.push("apache");
213	  if (webServers.length === 0 && (scan.webRoots ?? []).length > 0) webServers.push("nginx");
214	
215	  // Runtimes: from running-app runtimes and listening-port owners. Conservative.
216	  const runtimeBlob = [
217	    ...(scan.appDirs ?? []).map((a) => a.runtime || ""),
218	    ...(scan.ports ?? []).map((p) => p.proc || ""),
219	  ]
220	    .join(" ")
221	    .toLowerCase();
222	  const runtimes: ("nodejs" | "python3")[] = [];
223	  if (/node|next|pm2/.test(runtimeBlob)) runtimes.push("nodejs");
224	  if (/python|gunicorn|uvicorn|celery/.test(runtimeBlob)) runtimes.push("python3");
225	
226	  return { dbEngines, dockerVolumes, composeDirs, verifyPorts, hasContainers, webServers, runtimes };
227	}
228	
229	const GiB = 1024 ** 3;
230	
231	/** Working headroom the transfer needs while images load/unpack. Mirrors the
232	 *  engine's pre-flight allowance in worker/migrate-real.ts so the wizard's
233	 *  "will it fit?" answer and the worker's refusal can never disagree. */
234	const MIGRATION_HEADROOM_BYTES = 2 * GiB;
235	void MIGRATION_HEADROOM_BYTES; // kept for reference; the worker owns the headroom allowance
236	
237	/**
238	 * Sum (in bytes) of the SELECTED migration items, plus the DB data-dir estimate
239	 * when a database engine was detected (databases are auto-included). Sizes come
240	 * from the read-only scan's human size labels; unknown-size items (custom folders,
241	 * Docker mounts) count as 0. Used both for the client storage panel and the
242	 * worker pre-flight — computed server-side here so the stored total is trusted.
243	 */
244	function selectedMigrationBytes(scan: ScanResult | undefined, selectedPaths: string[]): number {
245	  if (!scan || !scan.ok) return 0;
246	  const sizeByPath = new Map<string, number>();
247	  for (const w of scan.webRoots ?? []) sizeByPath.set(w.path, parseSizeLabel(w.sizeLabel));
248	  for (const h of scan.homes ?? []) sizeByPath.set(h.path, parseSizeLabel(h.sizeLabel));
249	  for (const a of scan.appDirs ?? []) sizeByPath.set(a.path, parseSizeLabel(a.sizeLabel));
250	  let total = 0;
251	  for (const p of selectedPaths) total += sizeByPath.get(p) ?? 0;
252	  // Databases are auto-included whenever an engine is present.
253	  const enginePresent = (scan.engines ?? []).some((e) => e.present);
254	  if (enginePresent) total += Math.max(0, scan.dbSizeBytes ?? 0);
255	  // CONTRACT — this is FILES ONLY (selected paths + the DB data-dir estimate).
256	  // It is stored as `items.totalBytes`, and the worker pre-flight reads it as
257	  // `fileBytes` and then adds the Docker image allowance + headroom ITSELF
258	  // (worker/migrate-real.ts). Adding Docker here as well made the engine count it
259	  // TWICE — a ~12 GB move was reported as needing 83.6 GB and refused. The wizard
260	  // displays the combined figure by computing its own file/Docker split
261	  // client-side; it never renders this value, so keep this files-only.
262	  return Math.round(total);
263	}
264	
265	/** Parse ID / VERSION_ID / PRETTY_NAME lines from `/etc/os-release` (never sourced). */
266	function parseOsRelease(stdout: string): { id: string; versionId: string; pretty: string } | null {
267	  const o: Record<string, string> = {};
268	  for (const line of (stdout ?? "").split("\n")) {
269	    const m = /^(ID|VERSION_ID|PRETTY_NAME)=(.*)$/.exec(line.trim());
270	    if (!m) continue;
271	    o[m[1]] = m[2].trim().replace(/^["']|["']$/g, "").slice(0, 128);
272	  }
273	  if (!o.ID && !o.PRETTY_NAME && !o.VERSION_ID) return null;
274	  return {
275	    id: (o.ID ?? "").toLowerCase().slice(0, 32),
276	    versionId: (o.VERSION_ID ?? "").slice(0, 32),
277	    pretty: o.PRETTY_NAME ?? "",
278	  };
279	}
