281	async function ownedTargetServer(serverId: string) {
282	  const user = await requireUser();
283	  const server = await db.server.findUnique({ where: { id: serverId } });
284	  if (!server) throw new Error("Not found");
285	  if (server.userId !== user.id && user.role !== "ADMIN") throw new Error("Forbidden");
286	  return { user, server };
287	}
