289	function toRow(
290	  m: {
291	    id: string;
292	    serverId: string;
293	    sourceHost: string;
294	    sourcePort: number;
295	    sourceUser: string;
296	    items: unknown;
297	    status: string;
298	    progress: number;
299	    step: string | null;
300	    log: string | null;
301	    lastError: string | null;
302	    createdAt: Date;
303	    finishedAt: Date | null;
304	  },
305	  server: { hostname: string; label: string | null } | null
306	): MigrationRow {
307	  const items = (m.items ?? {}) as {
308	    paths?: string[];
309	    databases?: { engine?: string; name?: string; user?: string }[];
310	    dbEngines?: string[];
311	  };
312	  // Databases are now auto-included per detected engine (no per-DB list). For the
313	  // client view, surface one row per engine; fall back to any legacy per-DB list.
314	  const dbView: MigrationDatabaseView[] =
315	    Array.isArray(items.databases) && items.databases.length
316	      ? items.databases.map((d) => ({
317	          engine: String(d.engine ?? ""),
318	          name: String(d.name ?? ""),
319	          user: String(d.user ?? ""),
320	        }))
321	      : Array.isArray(items.dbEngines)
322	        ? items.dbEngines.map((e) => ({ engine: String(e), name: "All databases", user: "root" }))
323	        : [];
324	  return {
325	    id: m.id,
326	    serverId: m.serverId,
327	    // Migration has no Prisma relation to Server (serverId is a plain FK), so the
328	    // caller resolves the server row and passes it in.
329	    serverName: server ? server.label || server.hostname : null,
330	    sourceHost: m.sourceHost,
331	    sourcePort: m.sourcePort,
332	    sourceUser: m.sourceUser,
333	    paths: Array.isArray(items.paths) ? items.paths : [],
334	    // Never expose any DB secret — dbView carries only non-sensitive fields.
335	    databases: dbView,
336	    status: m.status,
337	    progress: m.progress,
338	    step: m.step,
339	    log: m.log,
340	    lastError: m.lastError,
341	    createdAt: m.createdAt.toISOString(),
342	    finishedAt: m.finishedAt ? m.finishedAt.toISOString() : null,
343	  };
344	}
