348	/**
349	 * Start a migration onto one of the caller's Nxeon servers. Verifies TARGET
350	 * ownership, validates the source connection details, encrypts every source
351	 * secret, writes the Migration row (PENDING) and enqueues a MIGRATE job. Returns
352	 * the new migration id; never returns any secret.
353	 */
354	export async function createMigration(
355	  input: CreateMigrationInput
356	): Promise<{ error?: string; id?: string }> {
357	  const { user, server } = await ownedTargetServer(input.serverId);
358	
359	  // Rate-limit: a few migrations per user per 10 minutes is plenty and stops
360	  // credential-stuffing the wizard against arbitrary source hosts.
361	  const rl = checkRateLimit(`migrate:create:${user.id}`, { max: 5, windowMs: 10 * 60 * 1000 });
362	  if (!rl.ok) {
363	    return { error: `Too many migrations started — please wait ${rl.retryAfterSec}s and try again.` };
364	  }
365	
366	  const host = (input.sourceHost ?? "").trim();
367	  if (!host || host.length > 253 || !HOST_RE.test(host)) {
368	    return { error: "Enter a valid source host — an IP address or domain name." };
369	  }
370	
371	  const port = input.sourcePort ?? 22;
372	  if (!Number.isInteger(port) || port < 1 || port > 65535) {
373	    return { error: "SSH port must be between 1 and 65535." };
374	  }
375	
376	  const sourceUser = (input.sourceUser ?? "root").trim();
377	  if (!sourceUser || sourceUser.length > 64 || /\s/.test(sourceUser)) {
378	    return { error: "Enter the SSH username on the source server." };
379	  }
380	
381	  if (!input.sourcePassword || input.sourcePassword.length < 1) {
382	    return { error: "Enter the SSH password for the source server." };
383	  }
384	
385	  const paths = cleanPaths(input.paths);
386	
387	  // Derive the passwordless lift-and-shift plan from the scan + selected paths.
388	  // Databases are auto-included when an engine is detected — no DB password is
389	  // ever collected; the worker dumps via root's local socket/peer auth.
390	  const plan = derivePlan(input.scan, paths);
391	
392	  // Persist the (secret-free) detection snapshot alongside the plan so the
393	  // migration is traceable back to what auto-detection found. Reusing items
394	  // avoids a schema change (Migration.items is a Json column).
395	  const scanSnapshot =
396	    input.scan && input.scan.ok
397	      ? {
398	          webRoots: input.scan.webRoots?.slice(0, 40) ?? [],
399	          homes: input.scan.homes?.slice(0, 40) ?? [],
400	          databases: input.scan.databases?.slice(0, 60) ?? [],
401	          engines: input.scan.engines ?? [],
402	          // Exact engine variant + version — lets the worker install the MATCHING
403	          // engine on the target for a clean same-engine restore.
404	          dbEngines: input.scan.dbEngines ?? [],
405	          // Running-app discovery — informational, secret-free, for traceability.
406	          appDirs: input.scan.appDirs?.slice(0, 40) ?? [],
407	          containers: input.scan.containers?.slice(0, 30) ?? [],
408	          ports: input.scan.ports?.slice(0, 60) ?? [],
409	          services: input.scan.services?.slice(0, 30) ?? [],
410	          // Storage-guardrail + compatibility inputs (secret-free, for traceability
411	          // and the worker pre-flight).
412	          dbSizeBytes: Math.max(0, input.scan.dbSizeBytes ?? 0),
413	          sourceOs: input.scan.sourceOs ?? null,
414	          sourceArch: input.scan.sourceArch ?? null,
415	          synthetic: !!input.scan.synthetic,
416	        }
417	      : undefined;
418	
419	  // Trusted server-side total of what will be migrated (bytes) — carried through
420	  // items so the worker's pre-flight guard can compare it to target free disk
421	  // without re-scanning. No schema change: Migration.items is a Json column.
422	  const totalBytes = selectedMigrationBytes(input.scan, paths);
423	
424	  const items = {
425	    paths,
426	    dbEngines: plan.dbEngines,
427	    dockerVolumes: plan.dockerVolumes,
428	    composeDirs: plan.composeDirs,
429	    verifyPorts: plan.verifyPorts,
430	    hasContainers: plan.hasContainers,
431	    webServers: plan.webServers,
432	    runtimes: plan.runtimes,
433	    totalBytes,
434	    // Explicit consent only — coerced to a real boolean so nothing else can ride
435	    // in on this field, and only ever true when the customer ticked the box.
436	    useVolumeForDocker: input.useVolumeForDocker === true,
437	    ...(scanSnapshot ? { scan: scanSnapshot } : {}),
438	  };
439	
440	  const migration = await db.migration.create({
441	    data: {
442	      userId: user.id,
443	      serverId: server.id,
444	      sourceHost: host,
445	      sourcePort: port,
446	      sourceUser,
447	      sourcePasswordEnc: encryptSecret(input.sourcePassword),
448	      items,
449	      status: "PENDING",
450	      progress: 0,
451	      step: "Queued",
452	    },
453	  });
454	
455	  // Enqueue the worker job. serverId ties the job to the target (cascade delete +
456	  // traceability); the handler loads everything else from payload.migrationId.
457	  await db.job.create({
458	    data: {
459	      type: "MIGRATE",
460	      serverId: server.id,
461	      payload: { migrationId: migration.id },
462	    },
463	  });
464	
465	  await db.auditLog.create({
466	    data: {
467	      userId: user.id,
468	      action: "migration.create",
469	      detail: `${migration.id} ${sourceUser}@${host}:${port} -> ${server.hostname} (${paths.length} paths, ${plan.dbEngines.length} db engine(s), ${plan.composeDirs.length} compose)`,
470	    },
471	  });
472	
473	  revalidatePath("/dashboard/migrate");
474	  return { id: migration.id };
475	}
