477	/**
478	 * READ-ONLY auto-detection of a source box for the beginner wizard. Verifies the
479	 * caller owns the TARGET server (authz + a stricter rate limit than create),
480	 * validates the source connection details, then SSHes into the source and
481	 * inventories web roots / home directories / databases — never writing anything
482	 * on the source and never persisting the supplied credentials.
483	 *
484	 * The plaintext SSH/DB passwords are used in-memory for this one call only and
485	 * are NOT stored anywhere; the client re-supplies them to createMigration once
486	 * the customer confirms what to move. Returns a secret-free ScanResult.
487	 *
488	 * In SANDBOX (staging) this returns realistic SYNTHETIC results and never opens
489	 * a real SSH connection, so staging stays fully self-contained.
490	 */
491	export async function scanSource(input: {
492	  serverId: string;
493	  sourceHost: string;
494	  sourcePort?: number;
495	  sourceUser?: string;
496	  sourcePassword: string;
497	  dbUser?: string;
498	  dbPassword?: string;
499	}): Promise<{ error?: string; scan?: ScanResult }> {
500	  const { user } = await ownedTargetServer(input.serverId);
501	
502	  // Scanning SSHes into an arbitrary customer-named host, so throttle it harder
503	  // than migration creation to stop the wizard being used to probe hosts.
504	  const rl = checkRateLimit(`migrate:scan:${user.id}`, { max: 8, windowMs: 10 * 60 * 1000 });
505	  if (!rl.ok) {
506	    return { error: `Too many scans — please wait ${rl.retryAfterSec}s and try again.` };
507	  }
508	
509	  const host = (input.sourceHost ?? "").trim();
510	  if (!host || host.length > 253 || !HOST_RE.test(host)) {
511	    return { error: "Enter a valid source host — an IP address or domain name." };
512	  }
513	  const port = input.sourcePort ?? 22;
514	  if (!Number.isInteger(port) || port < 1 || port > 65535) {
515	    return { error: "SSH port must be between 1 and 65535." };
516	  }
517	  const sourceUser = (input.sourceUser ?? "root").trim();
518	  if (!sourceUser || sourceUser.length > 64 || /\s/.test(sourceUser)) {
519	    return { error: "Enter the SSH username on the source server." };
520	  }
521	  if (!input.sourcePassword || input.sourcePassword.length < 1) {
522	    return { error: "Enter the SSH password for the source server." };
523	  }
524	
525	  await db.auditLog.create({
526	    data: { userId: user.id, action: "migration.scan", detail: `${sourceUser}@${host}:${port}` },
527	  }).catch(() => {});
528	
529	  // SANDBOX: never touch the outside world — hand back synthetic detection.
530	  if (SANDBOX) {
531	    return { scan: syntheticScan({ dbPassword: input.dbPassword }) };
532	  }
533	
534	  // Hard overall timeout so a slow/hostile source can't hang the request.
535	  const HARD_TIMEOUT_MS = 90_000;
536	  try {
537	    const scan = await Promise.race<ScanResult>([
538	      detectSource({
539	        host,
540	        port,
541	        user: sourceUser,
542	        password: input.sourcePassword,
543	        dbUser: input.dbUser?.trim() || undefined,
544	        dbPassword: input.dbPassword || undefined,
545	      }),
546	      new Promise<ScanResult>((_, reject) =>
547	        setTimeout(() => reject(new Error("Scan timed out — the source server took too long to respond.")), HARD_TIMEOUT_MS)
548	      ),
549	    ]);
550	    return { scan };
551	  } catch (e: any) {
552	    const msg = `${e?.message ?? e}`;
553	    // Map the common connection failures to friendly, non-leaky copy.
554	    if (/authentication|denied|password/i.test(msg)) {
555	      return { error: "Couldn't sign in to the source server — check the SSH username and password." };
556	    }
557	    if (/ECONNREFUSED|ETIMEDOUT|EHOSTUNREACH|ENOTFOUND|timed out|getaddrinfo/i.test(msg)) {
558	      return { error: "Couldn't reach the source server — check the host and SSH port." };
559	    }
560	    return { error: "We couldn't scan that server. Double-check the details and try again." };
561	  }
562	}
