564	// ---- Target free-space + OS probe (storage & compatibility guardrails) ------
565	
566	export type TargetInfo = {
567	  /** null when the server is unreachable / df couldn't be parsed → soft warning. */
568	  disk: { totalBytes: number; usedBytes: number; availBytes: number } | null;
569	  os: { id: string; versionId: string; pretty: string } | null;
570	  arch: string | null;
571	  /**
572	   * Capacity of the LARGEST attached-but-unformatted block device (a volume the
573	   * customer added but hasn't used yet), or null if there isn't one.
574	   *
575	   * This is capacity that is available **only if the customer chooses to use it**
576	   * — the engine can format it and relocate the container stores onto it, but it
577	   * never does so on its own (see `useVolumeForDocker`). Volumes are portable
578	   * add-on storage, and mounting a system path on one makes it undetachable, so
579	   * the wizard presents this as an opt-in, not as free space.
580	   *
581	   * The LARGEST, not the sum: separate volumes are separate filesystems and the
582	   * engine uses exactly one. They are deliberately never combined into an LVM
583	   * pool — that would weld them together and destroy the portability of all of
584	   * them at once.
585	   */
586	  spareDiskBytes?: number | null;
587	  /**
588	   * How many unused volumes are attached. 2+ means the panel should say that only
589	   * the largest can be used, so the customer isn't left expecting them to add up.
590	   */
591	  spareDiskCount?: number | null;
592	};
593	
594	/**
595	 * Probe a destination Nxeon server (owner-only) for its root-filesystem free
596	 * space and OS/architecture, so the wizard can show the storage headroom and the
597	 * OS-compatibility guardrail. Read-only: `df -B1`, `uname -m`, and a grep of
598	 * `/etc/os-release`. In SANDBOX returns synthetic values (never opens SSH).
599	 *
600	 * Failure is graceful: if the server is unreachable or df can't be parsed we
601	 * return `disk: null` (the UI shows "couldn't read free space" and allows the
602	 * migration with a soft warning rather than a hard block). OS falls back to the
603	 * server's known OS template; arch defaults to x86_64 (all our VMs are x86_64).
604	 */
605	export async function targetDiskFree(
606	  serverId: string
607	): Promise<{ error?: string; info?: TargetInfo }> {
608	  const { server } = await ownedTargetServer(serverId);
609	
610	  // OS fallback from the known OS template (works even if the box is unreachable).
611	  const tmpl = await db.osTemplate
612	    .findUnique({ where: { id: server.osTemplateId }, select: { family: true, version: true, name: true } })
613	    .catch(() => null);
614	  const osFallback = tmpl
615	    ? {
616	        id: (tmpl.family || "linux").toLowerCase(),
617	        versionId: tmpl.version || "",
618	        pretty: `${tmpl.name}${tmpl.version ? ` ${tmpl.version}` : ""}`,
619	      }
620	    : null;
621	
622	  if (SANDBOX) {
623	    // Synthetic 80 GB disk with ~63 GB free, matching our default plan sizing.
624	    return {
625	      info: {
626	        disk: { totalBytes: 80 * GiB, usedBytes: 17 * GiB, availBytes: 63 * GiB },
627	        os: osFallback ?? { id: "ubuntu", versionId: "24.04", pretty: "Ubuntu 24.04 LTS" },
628	        arch: "x86_64",
629	      },
630	    };
631	  }
632	
633	  // Need dedicatedIp to compute the SSH connection target (dedicated → :22).
634	  const full = await db.server.findUnique({
635	    where: { id: server.id },
636	    include: { dedicatedIp: true },
637	  });
638	
639	  try {
640	    const info = await withServerSsh(full as any, async (conn) => {
641	      // Root filesystem size/used/avail in bytes.
642	      const dfr = await exec(
643	        conn,
644	        "df -B1 --output=size,used,avail / 2>/dev/null | tail -n1",
645	        QUICK_TIMEOUT_MS
646	      );
647	      const nums = (dfr.stdout || "").trim().split("\n").pop()?.trim().split(/\s+/).map(Number) ?? [];
648	      let disk: TargetInfo["disk"] = null;
649	      if (nums.length >= 3 && nums.slice(0, 3).every((n) => Number.isFinite(n) && n > 0)) {
650	        disk = { totalBytes: nums[0], usedBytes: nums[1], availBytes: nums[2] };
651	      }
652	      const un = await exec(conn, "uname -m 2>/dev/null", QUICK_TIMEOUT_MS).catch(() => ({ stdout: "" }) as any);
653	      const arch = ((un.stdout as string) || "").trim().replace(/[^A-Za-z0-9_-]/g, "").slice(0, 32) || null;
654	      const osr = await exec(
655	        conn,
656	        "grep -E '^(ID|VERSION_ID|PRETTY_NAME)=' /etc/os-release 2>/dev/null || true",
657	        QUICK_TIMEOUT_MS
658	      ).catch(() => ({ stdout: "" }) as any);
659	      const os = parseOsRelease((osr.stdout as string) || "") ?? osFallback;
660	      // Attached-but-unformatted disks (unused volumes the customer added).
661	      // Read-only probe, and it mirrors the engine's qualification bar exactly so
662	      // the panel can never promise space the engine would refuse to touch: a
663	      // disk counts only when nothing in its tree has a filesystem or mount, it
664	      // has no children, nothing holds it, `blkid` finds no signature at all,
665	      // and it is at least the engine's 4 GiB floor.
666	      let spareDiskBytes: number | null = null;
667	      let spareDiskCount: number | null = null;
668	      try {
669	        const lb = await exec(
670	          conn,
671	          "for d in $(lsblk -dn -o NAME,TYPE 2>/dev/null | awk '$2==\"disk\"{print $1}'); do " +
672	            "[ -n \"$(lsblk -n -o FSTYPE,MOUNTPOINT /dev/$d 2>/dev/null | tr -d ' \\n')\" ] && continue; " +
673	            "[ -n \"$(lsblk -no NAME /dev/$d 2>/dev/null | tail -n +2)\" ] && continue; " +
674	            "[ -n \"$(ls -A /sys/block/$d/holders 2>/dev/null)\" ] && continue; " +
675	            "blkid /dev/$d >/dev/null 2>&1 && continue; " +
676	            "sz=$(lsblk -bdn -o SIZE /dev/$d 2>/dev/null | tr -d ' '); " +
677	            "[ -z \"$sz\" ] && continue; " +
678	            "[ \"$sz\" -ge 4294967296 ] 2>/dev/null && echo \"$sz\"; done",
679	          QUICK_TIMEOUT_MS
680	        );
681	        const sizes = ((lb.stdout as string) || "")
682	          .split("\n")
683	          .map((s) => Number(s.trim()))
684	          .filter((n) => Number.isFinite(n) && n > 0);
685	        if (sizes.length) {
686	          // The LARGEST, never the sum — the engine uses exactly one volume and
687	          // does not combine them, so summing would promise space that no single
688	          // filesystem will ever have. The count lets the panel say so plainly.
689	          spareDiskCount = sizes.length;
690	          spareDiskBytes = Math.max(...sizes);
691	        }
692	      } catch {
693	        /* best-effort: absence just means we report root-only free space */
694	      }
695	      return { disk, os, arch: arch ?? "x86_64", spareDiskBytes, spareDiskCount };
696	    });
697	    return { info };
698	  } catch {
699	    // Unreachable / probe error → soft warning (no hard block).
700	    return { info: { disk: null, os: osFallback, arch: "x86_64" } };
701	  }
702	}
