762	/**
763	 * Candidate domains to point at the migration's target server, cheapest source
764	 * first. Ownership-checked (the migration must be the caller's).
765	 *
766	 *   1. `Domain` rows — domains the customer registered with us.
767	 *   2. Websites already configured on the target server.
768	 *   3. Hostnames inferable from the STORED scan snapshot (`Migration.items.scan`)
769	 *      — web-root folders are conventionally named after the vhost. The snapshot
770	 *      does not record nginx/apache `server_name` values, so this is a best-effort
771	 *      read of what was already captured; we never re-scan the source.
772	 */
773	export async function getMigrationDnsInfo(migrationId: string): Promise<MigrationDnsInfo> {
774	  const user = await requireUser();
775	
776	  const m = await db.migration.findUnique({ where: { id: migrationId } });
777	  if (!m) return { error: "Migration not found." };
778	  if (m.userId !== user.id && user.role !== "ADMIN") return { error: "Not your migration." };
779	
780	  const server = await db.server.findUnique({
781	    where: { id: m.serverId },
782	    select: { hostname: true, label: true, ipAddress: true, dedicatedIp: { select: { address: true } } },
783	  });
784	
785	  const seen = new Set<string>();
786	  const candidates: DnsCandidate[] = [];
787	  const push = (raw: string | null | undefined, source: DnsCandidate["source"]) => {
788	    const host = cleanHostname(raw ?? "");
789	    if (!host || seen.has(host)) return;
790	    seen.add(host);
791	    candidates.push({ host, source });
792	  };
793	
794	  const domains = await db.domain.findMany({
795	    where: { userId: m.userId },
796	    select: { name: true },
797	    orderBy: { name: "asc" },
798	    take: 50,
799	  });
800	  for (const d of domains) push(d.name, "registered");
801	
802	  const sites = await db.website.findMany({
803	    where: { serverId: m.serverId },
804	    select: { domain: true },
805	    take: 50,
806	  });
807	  for (const s of sites) push(s.domain, "website");
808	
809	  // Only what the scan already stored — no new source-scanning here.
810	  const items = (m.items ?? {}) as { scan?: { webRoots?: { path?: string }[] } };
811	  for (const w of items.scan?.webRoots ?? []) {
812	    if (w?.path) push(hostnameFromPath(w.path), "scan");
813	  }
814	
815	  return {
816	    targetIp: server?.dedicatedIp?.address ?? server?.ipAddress ?? null,
817	    targetName: server ? server.label || server.hostname : null,
818	    candidates: candidates.slice(0, 40),
819	    cloudflareConnected: readStoredCloudflare(user.cloudflareTokenEnc) !== null,
820	  };
821	}
822	
823	/**
824	 * Point one hostname at the migration's TARGET server by upserting an A record in
825	 * the customer's Cloudflare zone — the last manual step of an otherwise one-click
826	 * migration.
827	 *
828	 * Guards: requireUser + migration ownership, rate-limited, and the hostname is
829	 * re-validated server-side (`cleanHostname` inside pointHostnameToIp) because
830	 * this one legitimately comes from customer input (the "enter a domain" box).
831	 * The record is DNS-only (proxied=false) so the name resolves to the server
832	 * itself and Let's Encrypt HTTP-01 validation can succeed there.
833	 */
834	export async function pointMigrationDns(
835	  migrationId: string,
836	  hostname: string
837	): Promise<{ ok: true; message: string } | { ok: false; error: string }> {
838	  const user = await requireUser();
839	
840	  const m = await db.migration.findUnique({ where: { id: migrationId } });
841	  if (!m) return { ok: false, error: "Migration not found." };
842	  if (m.userId !== user.id && user.role !== "ADMIN") return { ok: false, error: "Not your migration." };
843	
844	  const rl = checkRateLimit(`migrate:dns:${user.id}`, { max: 20, windowMs: 60_000 });
845	  if (!rl.ok) return { ok: false, error: `Too many requests — retry in ${rl.retryAfterSec}s.` };
846	
847	  const server = await db.server.findUnique({
848	    where: { id: m.serverId },
849	    select: { ipAddress: true, dedicatedIp: { select: { address: true } } },
850	  });
851	  const ip = server?.dedicatedIp?.address ?? server?.ipAddress ?? null;
852	  if (!ip) {
853	    return { ok: false, error: "Your new server doesn't have a public IP yet — try again shortly." };
854	  }
855	
856	  const res = await pointHostnameToIp({
857	    user: { id: user.id, cloudflareTokenEnc: user.cloudflareTokenEnc },
858	    hostname,
859	    ip,
860	  });
861	  if (!res.ok) return { ok: false, error: res.error };
862	
863	  await db.auditLog.create({
864	    data: {
865	      userId: user.id,
866	      action: "migration.dns",
867	      detail: `${res.hostname} A → ${ip}${res.simulated ? " (sandbox)" : ""}`,
868	    },
869	  });
870	
871	  return {
872	    ok: true,
873	    message: res.simulated
874	      ? `Sandbox: pretended to point ${res.hostname} at ${ip} (DNS-only). Nothing was sent to Cloudflare.`
875	      : `${res.hostname} now points at ${ip} (A record ${res.action}, DNS-only). It can take a few minutes for visitors to see the new server.`,
876	  };
877	}
