/**
 * One-click: point apex + www at the platform's public IP.
 *
 * ADD BEFORE DELETE, per host. This used to delete every apex/www A record and
 * only then add the replacements — so a registrar hiccup, a rate limit or a
 * network blip in between took the domain DARK and left it that way, with an
 * error message that did not say the old records were already gone. That is the
 * "six domains dark while the run scored 4/4" failure shape: destructive work
 * done first, on the assumption the constructive half cannot fail.
 *
 * The new order is also idempotent — an A record already pointing at `ip` is
 * kept rather than churned — so clicking twice is free, and a half-finished run
 * can simply be retried.
 */
export async function pointDomainAtServer(domainId: string): Promise<{ error?: string }> {
  let ctx;
  try {
    ctx = await ownedDomain(domainId);
  } catch (e: any) {
    return { error: e.message };
  }
  const ip = process.env.PUBLIC_IP;
  if (!ip) {
    return {
      error:
        "This platform doesn't have a public IP configured, so there is nothing to point the domain at. " +
        "Contact support — this is a platform configuration problem, not something you can fix from here.",
    };
  }

  const done: string[] = [];
  try {
    const recs = await listRecords(ctx.domain.name);
    for (const host of ["", "www"]) {
      const label = host === "" ? ctx.domain.name : `www.${ctx.domain.name}`;
      const existing = recs.filter((r) => r.host === host && r.type === "A");
      const keep = existing.find((r) => r.answer === ip);
      // Constructive half FIRST: the name resolves somewhere at every instant.
      if (!keep) await addRecord(ctx.domain.name, { host, type: "A", answer: ip, ttl: 300 });
      // Only now retire the records that point elsewhere.
      for (const r of existing) {
        if (keep && r.id === keep.id) continue;
        await deleteRecord(ctx.domain.name, r.id);
      }
      done.push(label);
    }
  } catch (e: any) {
    const reason = String(e?.message ?? e).slice(0, 200);
    return {
      error:
        `Your DNS provider rejected part of this change (${reason}). ` +
        (done.length > 0
          ? `${done.join(" and ")} ${done.length === 1 ? "was" : "were"} pointed at ${ip} and ${done.length === 1 ? "is" : "are"} live; the rest was not changed. `
          : "Nothing was changed and your existing records are untouched. ") +
        `Wait a minute and click Point at server again — it is safe to repeat.`,
    };
  }
  revalidatePath(`/dashboard/domains/${domainId}`);
  return {};
}

