/**
 * A TypeScript parameter type is a compile-time comment on a network endpoint.
 *
 * Every export of this file is POST-able with any JSON the caller likes, so the
 * `"OPEN" | "CLOSED"` annotations below constrained the components and nothing
 * else. `TicketStatus` also contains ANSWERED and CUSTOMER_REPLY — both writable
 * here — so a customer could stamp their own ticket ANSWERED and drop it out of
 * the support queue's "needs a reply" view without anyone having replied. Values
 * outside the enum reached Prisma and threw, which surfaces as a server error
 * page rather than a message. Both are fixed by validating at the boundary.
 */
const TICKET_STATUS_CHOICES = ["OPEN", "CLOSED"] as const;
const TICKET_PRIORITY_CHOICES = ["LOW", "NORMAL", "HIGH", "URGENT"] as const;

export async function setTicketStatus(ticketId: string, status: "OPEN" | "CLOSED") {
  const user = await requireUser();
  if (!TICKET_STATUS_CHOICES.includes(status as (typeof TICKET_STATUS_CHOICES)[number])) {
    throw new Error("A ticket can only be reopened or closed from here.");
  }
  const ticket = await db.ticket.findUnique({ where: { id: ticketId } });
  if (!ticket) throw new Error("Not found");
  if (ticket.userId !== user.id && user.role !== "ADMIN") throw new Error("Forbidden");
  await db.ticket.update({ where: { id: ticketId }, data: { status } });
  revalidatePath(`/dashboard/support`);
  revalidatePath(`/dashboard/support/${ticketId}`);
  revalidatePath(`/admin/support`);
  revalidatePath(`/admin/support/${ticketId}`);
}

export async function setTicketPriority(ticketId: string, priority: "LOW" | "NORMAL" | "HIGH" | "URGENT") {
  await requireAdmin();
  if (!TICKET_PRIORITY_CHOICES.includes(priority as (typeof TICKET_PRIORITY_CHOICES)[number])) {
    throw new Error("Priority must be one of: LOW, NORMAL, HIGH, URGENT.");
  }
  await db.ticket.update({ where: { id: ticketId }, data: { priority } });
  revalidatePath(`/admin/support`);
  revalidatePath(`/admin/support/${ticketId}`);
