import { test } from "node:test";
import assert from "node:assert/strict";
import { readFileSync } from "node:fs";
import { join } from "node:path";

/**
 * Structural guards over the CUSTOMER-FACING SERVER ACTIONS.
 *
 * These are the functions the portal calls to act on a customer's behalf, and
 * they are the widest attack surface in the product for one reason that is easy
 * to forget while reading them: **every export of a `"use server"` file is a
 * public network endpoint**. Not "callable from the page that imports it" —
 * callable by a stranger with curl. That property is what turned
 * `verifyTotpForUser` into an unauthenticated 2FA brute-force oracle
 * (QA-PRELAUNCH P0-2) and is why `lib/safe-next.ts` and `lib/totp-verify.ts`
 * exist as plain modules.
 *
 * A reviewer can hold that in their head for one file. Nobody holds it for
 * fifteen, forever, while adding a sixteenth. So it is asserted here instead.
 *
 * ── WHY THE SOURCE IS STRIPPED OF COMMENTS FIRST ─────────────────────────────
 * This codebase documents its incidents in the code, at length. A tripwire that
 * greps raw source for `assertNotImpersonating` matches the comment explaining
 * why the guard matters — so it passes on a function whose guard was deleted and
 * whose comment survived, which is the exact edit a careless refactor makes.
 * `stripComments` removes comments (and only comments) before anything is
 * matched, so every assertion below is about executable code.
 */

const LIB = join(import.meta.dirname, "..", "lib");

/* ------------------------------------------------------------------ *
 * Source utilities
 * ------------------------------------------------------------------ */

/**
 * Remove `//` and slash-star comments while preserving string and template
 * literals verbatim (a `"https://…"` is not a comment, and neither is the `//`
 * inside `/^https?:\/\//`). Replaces each comment with a single space so token
 * boundaries survive.
 */
export function stripComments(src: string): string {
  let out = "";
  let i = 0;
  const n = src.length;
  let quote: string | null = null;

  while (i < n) {
    const c = src[i];
    const next = src[i + 1];

    if (quote) {
      out += c;
      if (c === "\\") {
        // Escape: copy the escaped character too, so `\"` never closes a string.
        if (i + 1 < n) out += src[i + 1];
        i += 2;
        continue;
      }
      if (c === quote) quote = null;
      i++;
      continue;
    }

    if (c === '"' || c === "'" || c === "`") {
      quote = c;
      out += c;
      i++;
      continue;
    }

    if (c === "/" && next === "/") {
      while (i < n && src[i] !== "\n") i++;
      out += " ";
      continue;
    }

    if (c === "/" && next === "*") {
      i += 2;
      while (i < n && !(src[i] === "*" && src[i + 1] === "/")) i++;
      i += 2;
      out += " ";
      continue;
    }

    out += c;
    i++;
  }
  return out;
}

function source(file: string): string {
  return stripComments(readFileSync(join(LIB, file), "utf8"));
}

/** Every `export async function NAME` in a (comment-stripped) module. */
function exportedActions(src: string): string[] {
  return [...src.matchAll(/export\s+async\s+function\s+([A-Za-z0-9_$]+)\s*\(/g)].map((m) => m[1]);
}

/**
 * The body of `export async function NAME`, by brace matching from its opening
 * `{`. Braces inside strings are ignored — every string literal in these files
 * is balanced anyway, but template literals interpolate `${…}` and must not be
 * allowed to unbalance the count.
 */
function bodyOf(src: string, name: string): string {
  const decl = new RegExp(`export\\s+async\\s+function\\s+${name}\\s*\\(`).exec(src);
  assert.ok(decl, `expected to find an exported action named ${name}`);
  let i = src.indexOf("{", decl.index);
  assert.ok(i > -1, `no body found for ${name}`);
  const start = i;
  let depth = 0;
  let quote: string | null = null;
  for (; i < src.length; i++) {
    const c = src[i];
    if (quote) {
      if (c === "\\") {
        i++;
        continue;
      }
      if (c === quote) quote = null;
      continue;
    }
    if (c === '"' || c === "'" || c === "`") {
      quote = c;
      continue;
    }
    if (c === "{") depth++;
    else if (c === "}") {
      depth--;
      if (depth === 0) return src.slice(start, i + 1);
    }
  }
  assert.fail(`unbalanced body for ${name}`);
}

/* ------------------------------------------------------------------ *
 * 0. The stripper itself must bite
 * ------------------------------------------------------------------ */

test("stripComments removes the incident notes a naive grep would match", () => {
  const src = `
    // Spend path: this needs assertNotImpersonating().
    /* debitWallet is called below — see assertNotImpersonating. */
    export async function pay() { await debitWallet(tx, id, 1); }
  `;
  const stripped = stripComments(src);
  assert.equal(stripped.includes("assertNotImpersonating"), false);
  assert.ok(stripped.includes("debitWallet(tx, id, 1)"));
});

test("stripComments leaves string and regex contents alone", () => {
  const src = String.raw`const a = "see https://example.com/x"; const b = /^https?:\/\//; // gone`;
  const stripped = stripComments(src);
  assert.ok(stripped.includes("https://example.com/x"), "a URL inside a string is not a comment");
  assert.ok(stripped.includes(String.raw`/^https?:\/\//`), "an escaped slash in a regex is not a comment");
  assert.equal(stripped.includes("gone"), false);
});

/* ------------------------------------------------------------------ *
 * 1. Nothing reaches a stranger unauthenticated
 * ------------------------------------------------------------------ */

/** The customer-facing action modules audited here. All carry `"use server"`. */
const ACTION_FILES = [
  "actions.ts",
  "actions-server.ts",
  "actions-server-lifecycle.ts",
  "actions-volumes.ts",
  "actions-domains.ts",
  "actions-domains-transfer.ts",
  "actions-disk.ts",
  "actions-gameplans.ts",
  "actions-growth.ts",
  "actions-affiliate.ts",
  "actions-onboarding.ts",
  "actions-support.ts",
  "actions-settings.ts",
  "actions-migrate.ts",
  "actions-ssl.ts",
  "actions-claude.ts",
] as const;

/**
 * Calls that establish WHO is asking. `owned*` are this codebase's per-resource
 * helpers, each of which starts with `requireUser()` and then proves ownership.
 */
const AUTH_MARKERS = [
  "requireUser(",
  "requireAdmin(",
  "requireArea(",
  "requireStaff(",
  "realUser(",
  "ownedServer(",
  "ownedVolume(",
  "ownedDomain(",
  "ownedCertificate(",
  "ownedTargetServer(",
  "assertInternalGrowthCaller(",
];

/**
 * The only endpoints that are SUPPOSED to answer an anonymous caller: the
 * sign-up / sign-in / sign-out trio. Each rate-limits itself; see lib/actions.ts.
 */
const INTENTIONALLY_PUBLIC = new Set(["register", "login", "logout"]);

test("every exported server action identifies its caller inside the function", () => {
  const unguarded: string[] = [];
  for (const file of ACTION_FILES) {
    const src = source(file);
    assert.ok(src.includes('"use server"'), `${file} should declare "use server"`);
    for (const name of exportedActions(src)) {
      if (INTENTIONALLY_PUBLIC.has(name)) continue;
      const body = bodyOf(src, name);
      if (!AUTH_MARKERS.some((m) => body.includes(m))) unguarded.push(`${file}:${name}`);
    }
  }
  assert.deepEqual(
    unguarded,
    [],
    "these exports are network-reachable by an anonymous caller with no identity check",
  );
});

/* ------------------------------------------------------------------ *
 * 2. No money moves while an admin is impersonating a customer
 * ------------------------------------------------------------------ */

/**
 * Calls that move a customer's money: a wallet debit, a wallet credit, a Stripe
 * Checkout opened in their name, or one of the helpers that wraps those.
 */
const MONEY_MARKERS = [
  "debitWallet(",
  "balanceCents: { increment",
  "createOrderCheckout(",
  "createResizeCheckout(",
  "createDiskExpandCheckout(",
  "placeOrder(",
  "applyResize(",
  "applyDiskExpand(",
  "settleFailedTransferIn(",
];

/**
 * Actions that move money WITHOUT the impersonation guard, by design — because
 * they are staff tools whose whole purpose is acting on someone else's balance,
 * or an internal reward path with its own caller check.
 *
 * The allowlist is self-policing: each entry must independently prove it is
 * staff-gated or internal, asserted below. An action cannot be quietly parked
 * here to dodge the guard.
 */
const STAFF_OR_INTERNAL_MONEY = new Map<string, string[]>([
  ["actions.ts:adminCreditUser", ["requireAdmin("]],
  ["actions-affiliate.ts:adminUpdatePayout", ["requireArea("]],
  ["actions-growth.ts:maybeRewardReferral", ["assertInternalGrowthCaller("]],
]);

function moneyActions(): { key: string; body: string }[] {
  const found: { key: string; body: string }[] = [];
  for (const file of ACTION_FILES) {
    const src = source(file);
    for (const name of exportedActions(src)) {
      const body = bodyOf(src, name);
      if (MONEY_MARKERS.some((m) => body.includes(m))) found.push({ key: `${file}:${name}`, body });
    }
  }
  return found;
}

test("every customer-facing action that moves money calls assertNotImpersonating", () => {
  const missing: string[] = [];
  for (const { key, body } of moneyActions()) {
    if (STAFF_OR_INTERNAL_MONEY.has(key)) continue;
    if (!body.includes("assertNotImpersonating(")) missing.push(key);
  }
  assert.deepEqual(
    missing,
    [],
    "an admin impersonating a customer could spend or move that customer's money here",
  );
});

test("the impersonation guard runs BEFORE the first money movement", () => {
  const late: string[] = [];
  for (const { key, body } of moneyActions()) {
    if (STAFF_OR_INTERNAL_MONEY.has(key)) continue;
    const guardAt = body.indexOf("assertNotImpersonating(");
    const moneyAt = Math.min(
      ...MONEY_MARKERS.map((m) => body.indexOf(m)).filter((n) => n >= 0),
    );
    if (guardAt < 0 || guardAt > moneyAt) late.push(key);
  }
  assert.deepEqual(late, [], "the guard must be reached before anything is charged or credited");
});

test("every money action exempted from the guard is genuinely staff-gated or internal", () => {
  const bodies = new Map(moneyActions().map((a) => [a.key, a.body]));
  for (const [key, required] of STAFF_OR_INTERNAL_MONEY) {
    const body = bodies.get(key);
    assert.ok(body, `${key} is allowlisted but no longer moves money — remove it from the list`);
    assert.ok(
      required.some((m) => body!.includes(m)),
      `${key} is exempt from assertNotImpersonating and must prove it is staff-gated (${required.join(", ")})`,
    );
  }
});

/* ------------------------------------------------------------------ *
 * 3. Credit-minting helpers are not endpoints
 * ------------------------------------------------------------------ */

test("no 'use server' module exports a function that mints signup credit", () => {
  for (const file of ACTION_FILES) {
    const names = exportedActions(source(file));
    assert.equal(
      names.includes("grantSignupCredit"),
      false,
      `${file} exports grantSignupCredit — that makes "credit an arbitrary userId" a public endpoint. ` +
        "It has one in-process caller and belongs as a private helper (see lib/actions.ts).",
    );
  }
});

test("the referral guard does not key on a client-supplied framework header", () => {
  const src = source("actions-growth.ts");
  const guard = /async function assertInternalGrowthCaller[\s\S]*?\n}/.exec(src);
  assert.ok(guard, "assertInternalGrowthCaller should still exist");
  // Next.js dispatches actions from a no-JS form POST with the action id in the
  // BODY and no `next-action` header at all, so treating a missing header as
  // "trusted internal call" waved that path straight through.
  assert.equal(
    guard[0].includes("next-action"),
    false,
    "the presence of the next-action header must not decide whether the caller is trusted",
  );
  assert.ok(guard[0].includes("realUser("), "the guard must resolve the acting account");
});

/* ------------------------------------------------------------------ *
 * 4. Read-then-write races: claim state with a compare-and-swap
 * ------------------------------------------------------------------ */

/**
 * Each of these reads a row, decides from the value it read, and then acts. A
 * plain `update` after such a read is a lost-update race that a double-click
 * reproduces: both requests see the old state and both act on it. The
 * compare-and-swap (`updateMany` with the read state in the WHERE clause) makes
 * exactly one of them win.
 */
const CAS_REQUIRED: { file: string; action: string; what: string }[] = [
  { file: "actions-claude.ts", action: "approveBuild", what: "runs an AI command plan as root over SSH" },
  { file: "actions-claude.ts", action: "rejectBuild", what: "races an approval of the same build" },
  { file: "actions-volumes.ts", action: "attachVolume", what: "hot-plugs one disk onto two servers" },
  { file: "actions-volumes.ts", action: "deleteVolume", what: "destroys a disk" },
];

for (const { file, action, what } of CAS_REQUIRED) {
  test(`${action} claims its state with a compare-and-swap (${what})`, () => {
    const body = bodyOf(source(file), action);
    assert.ok(
      body.includes("updateMany("),
      `${action} must claim the row with updateMany(...) guarded on the state it read`,
    );
    assert.ok(
      /count === 0/.test(body),
      `${action} must check the swap actually won (count === 0 means another request got there first)`,
    );
  });
}

test("renewNow still compare-and-swaps the expiry before charging", () => {
  // The original of this pattern, and the reason the others exist.
  const body = bodyOf(source("actions.ts"), "renewNow");
  const casAt = body.indexOf("updateMany(");
  const debitAt = body.indexOf("debitWallet(");
  assert.ok(casAt > -1 && debitAt > -1);
  assert.ok(casAt < debitAt, "the expiry swap must be won before the wallet is debited");
});

/* ------------------------------------------------------------------ *
 * 5. A unique-key collision is an outcome, not a crash
 * ------------------------------------------------------------------ */

test("addPortForward survives losing the race for a public port", () => {
  const body = bodyOf(source("actions-server.ts"), "addPortForward");
  // PortForward.publicPort is UNIQUE. Picking a port from a snapshot read and
  // inserting it unguarded threw a raw Prisma P2002 out of the action, which
  // reaches the customer as a server-error page with no message and no hint that
  // retrying works.
  assert.ok(body.includes("P2002"), "the unique-port collision must be handled, not thrown");
  assert.ok(
    /catch\s*\(/.test(body),
    "the insert must be wrapped so a collision can be retried instead of escaping",
  );
});

/* ------------------------------------------------------------------ *
 * 6. Never enqueue work the worker will reject
 * ------------------------------------------------------------------ */

test("every snapshot action normalises the name the worker will re-normalise", () => {
  const src = source("actions-server.ts");
  // worker/index.ts snapshotOp strips [^a-zA-Z0-9_] and throws on an empty
  // result. An action that queues a name the worker will reject has told the
  // customer their snapshot is on its way and then dropped it in the worker,
  // where they never see the failure.
  for (const action of ["createSnapshot", "deleteSnapshot", "rollbackSnapshot"]) {
    const body = bodyOf(src, action);
    assert.ok(
      body.includes("cleanSnapshotName("),
      `${action} must normalise the snapshot name before enqueuing it`,
    );
  }
});

test("rollbackSnapshot refuses a server that is not in a steady state", () => {
  const body = bodyOf(source("actions-server.ts"), "rollbackSnapshot");
  assert.ok(
    body.includes("RUNNING") && body.includes("STOPPED"),
    "a disk rollback needs a real VM in a steady state, like createSnapshot already required",
  );
});

/* ------------------------------------------------------------------ *
 * 7. Destructive DNS work happens after the constructive half
 * ------------------------------------------------------------------ */

test("pointDomainAtServer adds the new A record before deleting the old one", () => {
  const body = bodyOf(source("actions-domains.ts"), "pointDomainAtServer");
  const addAt = body.indexOf("addRecord(");
  const deleteAt = body.indexOf("deleteRecord(");
  assert.ok(addAt > -1 && deleteAt > -1, "the action should still add and delete A records");
  assert.ok(
    addAt < deleteAt,
    "deleting every apex/www A record first takes the domain dark if the add then fails",
  );
});

/* ------------------------------------------------------------------ *
 * 8. A TypeScript parameter type is not validation
 * ------------------------------------------------------------------ */

test("ticket status and priority are validated at the boundary, not by their types", () => {
  const src = source("actions-support.ts");
  const status = bodyOf(src, "setTicketStatus");
  assert.ok(
    status.includes("TICKET_STATUS_CHOICES"),
    'setTicketStatus is POST-able with any string; TicketStatus also contains ANSWERED, so a customer ' +
      "could drop their own ticket out of the support queue",
  );
  const priority = bodyOf(src, "setTicketPriority");
  assert.ok(priority.includes("TICKET_PRIORITY_CHOICES"), "setTicketPriority must validate its enum too");
});

/* ------------------------------------------------------------------ *
 * 9. Ownership is proven from the id that was passed in
 * ------------------------------------------------------------------ */

/**
 * Actions that take a resource id and act on that resource must resolve it
 * through an ownership helper (or an explicitly user-scoped query), never with a
 * bare `findUnique` whose result is then trusted. This lists the id-taking
 * customer actions and the ownership proof each one performs.
 */
const OWNERSHIP_PROOFS: { file: string; action: string }[] = [
  { file: "actions-server.ts", action: "getBackupJob" },
  { file: "actions-server.ts", action: "resizeServer" },
  { file: "actions-server.ts", action: "resetRootPassword" },
  { file: "actions-server.ts", action: "addPortForward" },
