  { file: "actions-volumes.ts", action: "attachVolume" },
  { file: "actions-volumes.ts", action: "detachVolume" },
  { file: "actions-volumes.ts", action: "deleteVolume" },
  { file: "actions-disk.ts", action: "expandServerDisk" },
  { file: "actions-ssl.ts", action: "requestCertificate" },
  { file: "actions-ssl.ts", action: "renewCertificate" },
  { file: "actions-ssl.ts", action: "deleteCertificate" },
  { file: "actions-ssl.ts", action: "toggleAutoRenew" },
  { file: "actions-migrate.ts", action: "createMigration" },
  { file: "actions-migrate.ts", action: "scanSource" },
  { file: "actions-migrate.ts", action: "targetDiskFree" },
  { file: "actions-migrate.ts", action: "getMigration" },
  { file: "actions-migrate.ts", action: "getMigrationDnsInfo" },
  { file: "actions-migrate.ts", action: "pointMigrationDns" },
  { file: "actions-claude.ts", action: "submitBuild" },
  { file: "actions-claude.ts", action: "approveBuild" },
  { file: "actions-claude.ts", action: "rejectBuild" },
  { file: "actions-domains.ts", action: "renewDomainAction" },
  { file: "actions-domains.ts", action: "toggleDomainAutoRenew" },
  { file: "actions-domains.ts", action: "addDnsRecord" },
  { file: "actions-domains.ts", action: "deleteDnsRecord" },
  { file: "actions-domains.ts", action: "pointDomainAtServer" },
  { file: "actions-domains-transfer.ts", action: "cancelTransferIn" },
  { file: "actions-support.ts", action: "replyTicket" },
  { file: "actions-support.ts", action: "setTicketStatus" },
];

/** Either an `owned*` helper, or an explicit user-scoped comparison / query. */
const OWNERSHIP_MARKERS = [
  "ownedServer(",
  "ownedVolume(",
  "ownedDomain(",
  "ownedCertificate(",
  "ownedTargetServer(",
  "userId: user.id",
  "userId !== user.id",
  "!== user.id",
];

test("every id-taking customer action proves ownership of that id", () => {
  const unproven: string[] = [];
  for (const { file, action } of OWNERSHIP_PROOFS) {
    const body = bodyOf(source(file), action);
    if (!OWNERSHIP_MARKERS.some((m) => body.includes(m))) unproven.push(`${file}:${action}`);
  }
  assert.deepEqual(
    unproven,
    [],
    "these take a resource id from the caller and never check the caller owns it",
  );
});

