const BLOCKED_NAMES = new Set(["localhost", "localhost.localdomain", "ip6-localhost"]);

/** Basic hostname sanity: letters/digits/hyphens/dots, or a literal IP. */
export function isPlausibleHost(host: string): boolean {
  if (!host || host.length > 253) return false;
  if (net.isIP(host)) return true;
  return /^(?!-)[a-zA-Z0-9-]{1,63}(?<!-)(\.(?!-)[a-zA-Z0-9-]{1,63}(?<!-))*$/.test(host);
}

/**
 * Normalize an arbitrary user string into a bare hostname: strips a scheme,
 * path, port, and surrounding whitespace, and lower-cases. Returns null if
 * nothing host-like remains.
 */
export function extractHost(input: string): string | null {
  let s = (input || "").trim();
  if (!s) return null;
  // If it looks like a URL, let URL() pull the host out (handles ports, paths).
  if (/^[a-z][a-z0-9+.-]*:\/\//i.test(s)) {
    try {
      s = new URL(s).hostname;
    } catch {
      return null;
    }
  } else {
    // Strip any path / query and a trailing :port (but keep bracketed IPv6).
    s = s.split("/")[0].split("?")[0];
    if (s.startsWith("[")) {
      const end = s.indexOf("]");
      if (end !== -1) s = s.slice(1, end);
    } else if (s.includes(":") && net.isIP(s) === 0) {
      s = s.split(":")[0];
    }
  }
  s = s.replace(/\.$/, "").toLowerCase();
  return s || null;
}

export type ResolvedHost = { host: string; addresses: string[] };

/**
 * Resolve `host` to its A/AAAA records and assert every one is a public address.
 * Throws BlockedHostError on any private / loopback / reserved target or on a
 * bare localhost. Returns the resolved addresses so callers can connect to a
 * vetted IP (defeating DNS rebinding).
 */
export async function resolvePublicHost(host: string): Promise<ResolvedHost> {
  const h = host.toLowerCase();
  if (BLOCKED_NAMES.has(h)) throw new BlockedHostError("This host is not allowed.");
  if (!isPlausibleHost(h)) throw new BlockedHostError("That doesn't look like a valid host.");

  // A literal IP: no DNS, just classify it directly.
  if (net.isIP(h)) {
    if (isBlockedIp(h)) throw new BlockedHostError("Private, loopback, and reserved addresses are not allowed.");
    return { host: h, addresses: [h] };
  }

  let results: { address: string }[];
  try {
    results = await lookup(h, { all: true });
  } catch {
    throw new BlockedHostError("Could not resolve that hostname.");
  }
  if (!results.length) throw new BlockedHostError("Could not resolve that hostname.");

  const addresses = results.map((r) => r.address);
  for (const addr of addresses) {
    if (isBlockedIp(addr)) {
      throw new BlockedHostError("This host resolves to a private or reserved address and is not allowed.");
    }
  }
  return { host: h, addresses };
}

