import { test } from "node:test";
import assert from "node:assert/strict";
import { readFileSync } from "node:fs";
import { join } from "node:path";
import { checkRateLimit, clientIp } from "../lib/rate-limit.ts";
import { stripComments } from "./customer-actions-guards.test.ts";

/**
 * THE LOGIN THROTTLE MUST BIND TO SOMETHING THE CALLER CANNOT CHOOSE.
 *
 * `login` in lib/actions.ts is the only thing standing between a known email
 * address and unlimited password guesses — and, once a password is known,
 * unlimited 2FA code guesses, because the TOTP challenge sits INSIDE the same
 * rate-limited call. It keys on `${email}:${ip}`.
 *
 * The `ip` half used to be `x-forwarded-for.split(",")[0]`, under a comment
 * asserting the first hop is the real client. It is the opposite. nginx forwards
 * with `$proxy_add_x_forwarded_for`, which expands to `$http_x_forwarded_for,
 * $remote_addr` — it APPENDS the peer it actually saw. So the header the app
 * receives is `<whatever the client typed>, <the client's real address>`, and the
 * leftmost entry is a free-text field the attacker fills in. Rotating it once per
 * request gave every attempt a fresh bucket, so the limiter never bound and the
 * lockout never fired.
 *
 * Measured on production before the fix:
 *   curl -H 'X-Forwarded-For: 203.0.113.77' https://<host>/api/tools/my-ip
 *   -> {"ip":"203.0.113.77","forwardedFor":"203.0.113.77, 51.79.162.96"}
 *
 * These tests drive the real limiter with the real header shape nginx produces.
 */

/** Exactly what the app receives behind one nginx hop. */
function nginxForwarded(clientClaimed: string | null, realPeer: string) {
  const value = clientClaimed ? `${clientClaimed}, ${realPeer}` : realPeer;
  return { get: (name: string) => (name.toLowerCase() === "x-forwarded-for" ? value : null) };
}

/** The login limiter's real key shape (lib/actions.ts). */
const loginKey = (email: string, ip: string) => `login:${email}:${ip}`;

test("clientIp ignores the entry the caller wrote and takes the one nginx appended", () => {
  const REAL = "51.79.162.96";
  assert.equal(clientIp(nginxForwarded("203.0.113.77", REAL)), REAL);
  assert.equal(clientIp(nginxForwarded("10.0.0.1, 8.8.8.8", REAL)), REAL);
  assert.equal(clientIp(nginxForwarded(null, REAL)), REAL);
});

test("clientIp falls back to x-real-ip when no X-Forwarded-For arrives", () => {
  const h = { get: (n: string) => (n.toLowerCase() === "x-real-ip" ? " 51.79.162.96 " : null) };
  assert.equal(clientIp(h), "51.79.162.96");
});

test("rotating X-Forwarded-For does NOT buy extra login attempts", () => {
  const email = `rotate-${Math.random().toString(36).slice(2)}@example.test`;
  const REAL_ATTACKER = "203.0.113.9";
  const MAX = 10; // the shipped default of `login_ratelimit_max`

  let allowed = 0;
  for (let i = 0; i < 40; i++) {
    // One forged leftmost entry per request — the whole evasion.
    const h = nginxForwarded(`198.51.100.${i}`, REAL_ATTACKER);
    if (checkRateLimit(loginKey(email, clientIp(h)), { max: MAX, windowMs: 15 * 60 * 1000 }).ok) {
      allowed++;
    }
  }

  assert.equal(
    allowed,
    MAX,
    "40 password attempts with a rotating X-Forwarded-For got through — the account lockout does not bind",
  );
});

test("the same attempts keyed on the forged leftmost entry sail straight past the cap", () => {
  // The pre-fix behaviour, asserted explicitly so the difference is not
  // theoretical: this is what the deleted expression did.
  const email = `legacy-${Math.random().toString(36).slice(2)}@example.test`;
  const firstHop = (h: { get(n: string): string | null }) =>
    (h.get("x-forwarded-for") ?? "").split(",")[0]?.trim() || "unknown";

  let allowed = 0;
