/**
 * Validate a customer-named SOURCE host and resolve it to a vetted PUBLIC
 * address.
 *
 * This module's whole job is to SSH, from inside the platform, into a machine
 * whose address, username and password the customer types into a form. `HOST_RE`
 * checked only that the string looked like a host — so `10.20.0.137`,
 * `127.0.0.1` and the Proxmox host's own address all passed. That made the
 * migration wizard three things it was never meant to be:
 *
 *   - an internal PORT SCANNER of 10.20.0.0/24, which is every other customer's
 *     VPS, distinguishable because `scanSource` reports "couldn't sign in"
 *     (something is listening and speaking SSH) separately from "couldn't reach"
 *     (nothing there);
 *   - an SSH CREDENTIAL-STUFFING engine against those same machines, since the
 *     password is supplied per attempt;
 *   - a way to point it at the hypervisor and the platform's own loopback.
 *
 * A real migration source is always a public IP at another provider, so refusing
 * private / loopback / link-local / reserved targets costs a legitimate customer
 * nothing. `resolvePublicHost` (lib/tools/net-guard.ts) also resolves the name
 * itself and rejects if ANY A/AAAA record is private, which closes the DNS
 * rebinding variant — a name that answers public on our check and private on the
 * connect. The vetted address is returned so the caller can connect to the IP we
 * actually checked rather than re-resolving.
 */
async function vettedSourceHost(
  raw: string | undefined,
): Promise<{ host: string; address: string } | { error: string }> {
  const host = (raw ?? "").trim();
  if (!host || host.length > 253 || !HOST_RE.test(host)) {
    return { error: "Enter a valid source host — an IP address or domain name." };
  }
  try {
    const resolved = await resolvePublicHost(host);
    return { host, address: resolved.addresses[0] ?? host };
  } catch (e) {
    if (e instanceof BlockedHostError) {
      return {
        error:
          `We can't migrate from ${host}: ${e.message} ` +
          `The source has to be a server reachable on the public internet — use its public IP address ` +
          `or a domain name that points at it, not a private/LAN address.`,
      };
    }
    return {
      error:
        `We couldn't look up ${host}. Check the spelling, or enter the source server's public IP address instead.`,
    };
  }
}

