      body.includes("vettedSourceHost("),
      `${action} must resolve and classify the source host before using it`,
    );
  }
  // And the vetting must be a real public-address check, not a regex.
  assert.ok(src.includes("resolvePublicHost("), "vetting must go through lib/tools/net-guard");

